window.READING_HELP_DATA = {"commit":"3d592ece6de8c4559987416a544fc215fd6d6921","version":"v2.7.0","terms":{"rpc":{"name":"RPC","meaning":"アプリがノードへ、名前を指定して処理を頼む窓口です。","example":"例：残高を尋ねる要求と、署名済みトランザクションを送る要求があります。"},"node":{"name":"ノード","meaning":"ネットワークに参加し、届いたデータをルールで確かめるコンピューターです。","example":"Rethは、その中の実行・検証・状態管理を担うソフトウェアです。"},"bytes":{"name":"バイト列","meaning":"データを小さな数の並びとして表したものです。文字や金額の項目が、送信用の形式にまとめられています。","example":"見方の例：送信用の数の並び → 項目を読み取る → 宛先や署名などを扱えるデータ。ここでは実際の署名済みデータの例は送信しません。"},"recover":{"name":"送信者の復元","meaning":"署名済みデータの署名などから、送信者のアドレスを求めて確かめる処理です。","example":"ウォレットを開いたり、秘密鍵を取り出したりする処理ではありません。署名の問題などで失敗する場合があります。"},"pool":{"name":"トランザクションプール","meaning":"まだブロックに取り込まれていないトランザクションを、ノードが検証して保持する場所です。","example":"プール追加の成功、ブロックへの取り込み、履歴の確定はそれぞれ別です。"},"hash":{"name":"ハッシュ","meaning":"データから計算する、識別に使う値です。","example":"送信の応答にハッシュが返っても、取り込みや確定が終わったことは示しません。"},"cli":{"name":"CLI・コマンド","meaning":"文字で指示を入力する操作の入口です。reth nodeはノードの起動を頼むコマンドです。","example":"この読解アプリではコマンドを実行せず、Rethがその指示をどう読むかをコードで確かめます。"},"evm":{"name":"EVM","meaning":"Ethereumのプログラムを、決められたルールで動かす仕組みです。","example":"実行結果として変わる残高やデータを、実行側のRethが検証します。"},"engine":{"name":"Engine API","meaning":"合意側のソフトウェアと、実行側のRethが要求や結果を受け渡す窓口です。","example":"ウォレット向けRPCの窓口と区別します。合意側は履歴の選択や確定を追います。"},"database":{"name":"データベース・DB","meaning":"ブロックや状態などを保存し、必要なときに読み出すための仕組みです。","example":"起動時には、どこに保存するかを決めて開きます。"},"genesis":{"name":"genesis","meaning":"チェーンの出発点となる最初の状態・ブロックです。","example":"ノードは選んだネットワークに対応する出発点を使います。"},"function":{"name":"関数・呼び出し","meaning":"処理をひとまとまりにし、必要な場所から使えるようにしたものです。","example":"fnの後が名前、丸かっこの中が受け取るデータ、{ }の中が処理のまとまりです。名前(...)でその処理を呼び出します。"},"argument":{"name":"引数・入力","meaning":"処理へ渡すデータです。丸かっこの中に並びます。","example":"tx: Bytesは「txという名前で、Bytesという種類のデータを受け取る」という指定です。"},"return":{"name":"戻り値・出力","meaning":"呼び出した処理から、呼び出し元へ返る結果です。","example":"関数宣言の -> の後は、返す結果の種類です。成功か失敗かを含めて返す場合もあります。"},"variable":{"name":"let・値の名前","meaning":"途中の結果を、後で使える名前に結びつけます。","example":"let handle = ... は、右側で得た値をhandleという名前で使えるようにする書き方です。"},"await":{"name":".await・Future","meaning":"この処理の結果が用意できるまで待つ場所です。RustではFutureという、処理の進行と結果を表す値を進めて待ちます。","example":"結果がまだ用意できない間は、ほかの処理へ実行を譲れます。asyncだけで別スレッドが作られるわけではありません。"},"question":{"name":"?・失敗を返す","meaning":"このResultに付く ? は、成功なら中身を取り出し、失敗なら現在の関数やasyncブロックからエラーを返します。","example":"失敗ならそこでエラーを返し、その後の成功処理へは進みません。ここではResultに付いた?の役割を説明しています。"},"double-question":{"name":"??・2段階の失敗","meaning":"ここでは返答を受け取れたかを確認し、その後、受け取ったプール追加結果が成功かを確認します。","example":"response_rx.await??の最初の?が受信の失敗、次の?がプール追加結果の失敗を扱います。"},"result":{"name":"Result・Ok・Err","meaning":"成功の値か、失敗の情報のどちらかを返す形です。","example":"Ok(値)は成功、Err(エラー)は失敗を表します。Ok(())の()は、成功時に追加のデータを返さないという形です。"},"type":{"name":"型","meaning":"扱うデータや結果の種類を指定するための約束です。","example":"例：Bytesはバイト列の種類です。B256はハッシュなど、32バイトの値を表す種類です。"},"borrow":{"name":"&self・&tx","meaning":"&は値を借りて使うことを表します。&selfは、この処理の対象を借りる指定です。","example":"ここでは元の持ち主が値を持ったまま、読み取る処理へ貸せます。"},"trait":{"name":"trait・Self","meaning":"型が提供する操作などの約束と、それを実装する型を表す書き方です。","example":"Selfは今の実装の型です。実装を差し替えられる境界を読むときに確かめます。"},"channel":{"name":"チャネル・oneshot","meaning":"別の処理へデータを渡すための経路です。oneshotで送れる返答は1回です。","example":"送信用の口を要求に添え、受信用の口を持つ側が結果を待ちます。"},"closure":{"name":"move・使う値を取り込む","meaning":"クロージャーやasyncブロックが、外側の値を自分の側へ取り込む指定です。値の型によって、所有権の移動やコピーが起きます。","example":"起動の入口では実行する処理をクロージャーとして渡します。送信経路のasync moveブロックでは、そこで必要な値を非同期処理へ取り込みます。"},"handle":{"name":"handle","meaning":"別の部品へ指示を出したり、その状態を待ったりするための値です。","example":"起動の入口では、起動後に得たhandleでノードの終了を待ちます。ほかの箇所では操作する相手が異なるため、周囲の処理も確認します。"},"thread":{"name":"スレッド・タスク","meaning":"スレッドはOSが処理を進める実行の単位です。非同期タスクは、待ちを含む処理を実行環境に進めてもらう単位です。","example":"両者は一対一とは限りません。どこで別の処理を始め、何を待つかを分けます。"},"poll":{"name":"poll・Pending","meaning":"非同期処理を進められるか確かめる呼び出しです。すぐには結果が出ないときはPendingを返します。","example":"後で再び進めてもらえるよう通知を予約する場合もあります。"},"jit":{"name":"JITの分岐","meaning":"実行時に処理をコンパイルする機能に関する分岐です。","example":"この起動の読解では、その補助処理の分岐を主線から外し、コマンド処理を渡す箇所に注目します。"},"async":{"name":"async","meaning":"待ちを含む処理を、Futureとして扱える形に書くための指定です。","example":"async関数を呼ぶとFutureが得られます。本体を進めるには、.awaitなどによるポーリングが必要です。asyncだけで別スレッドが作られるわけではありません。"},"logging":{"name":"ログに値を表示する ?","meaning":"trace! や info! などのログを記録する式では、? は続く値をデバッグ用の形で記録する指定です。","example":"例：trace!(?tx) の ?tx は値の記録方法です。work().await? のように、失敗時にエラーを返す ? とは役割が違います。"},"option-question":{"name":"?・値がなければここで戻る","meaning":"この行の ? は Option に付いています。Someなら中身の値を取り出し、Noneなら現在の関数からNoneを返します。","example":"同期の目標がなければ、ここでNoneを返して処理を終えます。この ? はエラーを返す説明ではありません。"},"block":{"name":"ブロック","meaning":"複数の処理の要求と、それらをまとめる情報を持つ記録の単位です。","example":"この読解では、その中のトランザクションを順に実行する箇所も確認します。"},"state":{"name":"状態","meaning":"ある時点の残高や、プログラムが保持するデータなどです。","example":"実行で変わる状態と、それを保存先へ確定する処理を分けて読みます。"},"receipt":{"name":"レシート","meaning":"トランザクションを実行した結果を表す記録です。","example":"送信要求へのハッシュの返答とは別で、実行が成功したかや使用したガスなどを扱います。"},"stage":{"name":"ステージ・パイプライン","meaning":"同期に必要な仕事を段階に分け、順に進める仕組みです。","example":"各段階の結果に応じ、進捗を更新したり、前の状態へ戻してやり直したりします。"},"unwind":{"name":"巻き戻し","meaning":"問題がある箇所より前の状態へ戻して、やり直せるようにする処理です。","example":"この同期の入口では、巻き戻しの指示を受けた場合を通常の進捗更新と分けています。"},"payload":{"name":"ペイロード・ブロック候補","meaning":"提案するブロックの実行側の中身です。トランザクションなどを選んで組み立てます。","example":"候補を作ったことだけで、ネットワークでの採用や履歴の確定を意味しません。"},"notification":{"name":"通知・ExEx","meaning":"ノード内の出来事を拡張機能へ伝えるためのデータです。ExExは実行結果を利用する拡張機能です。","example":"通知経路へ渡すことと、受け手の拡張機能が処理を終えることは分けます。"},"json":{"name":"JSON","meaning":"データの項目と値を、文字で表す形式です。","example":"ここではRethに組み込まれたmainnet用の最初の状態の設定を読み取ります。"},"chain-config":{"name":"チェーンの設定","meaning":"どのネットワークのルールや最初の状態を使うかを定める情報です。","example":"mainnet、テスト用ネットワークなどでは、同じ設定を使うとは限りません。"},"chain-id":{"name":"チェーンID","meaning":"どのネットワーク向けの要求かを区別する番号です。","example":"送信要求に番号がある場合、この検証ではノード側の番号と比較します。"},"expect":{"name":"expect・値がなければ実行を止める","meaning":"Resultの失敗やOptionの値なしを、このプログラムの想定外としてpanicを起こす操作です。","example":"例えば、設定読み込みのResultに使うと、失敗時に指定メッセージでpanicを起こします。?で呼び出し元へエラーを返す操作とは区別します。"},"if":{"name":"if・条件で分ける","meaning":"条件が成り立つときに、その後の処理のまとまりを実行します。","example":"elseがある場合は、条件が成り立たないときの処理を表します。"},"for-loop":{"name":"for・順に処理する","meaning":"複数の値を一つずつ取り出し、同じ処理を繰り返します。","example":"for tx in ... なら、取り出した一つの値をtxという名前で使います。"},"match":{"name":"match・結果の形で分ける","meaning":"得られた値がどの形かに応じ、実行する処理を選びます。","example":"結果の種類ごとに、続ける処理や戻る処理を分けられます。この箇所の具体的な分岐は、日本語と行の対応で確かめられます。"},"early-return":{"name":"return・ここで戻る","meaning":"現在の関数やブロックから、その場で結果を返して処理を終えます。","example":"後ろに書かれた処理を実行せず、呼び出した側へ戻ります。"},"for-context":{"name":"for・前後の書き方で役割を確かめる","meaning":"forは使う場所によって役割が変わります。for 値 in 一覧 は繰り返し、impl 操作の約束 for 型 は、その型へ操作を実装する指定です。","example":"ここでどちらの役割かは、前後のコードと、その行に対応する説明で確かめます。"},"for-implementation":{"name":"for・操作の約束をこの型に実装する","meaning":"impl ... for ... は、ある型が操作の約束を実装する書き方です。この行は繰り返し処理ではありません。","example":"ここではNetworkManagerがFutureとして処理を進められるように、後ろでpollを実装します。"},"peer":{"name":"通信相手・ピア","meaning":"同じネットワークに参加して、データをやり取りする別のノードです。","example":"相手の評価値は、このノードが通信相手を扱うための情報です。履歴の確定への投票数ではありません。"},"gas":{"name":"ガス","meaning":"処理に必要な計算などの量を数えるための単位です。","example":"候補ブロックには使える量の枠があり、一件の要求の上限が残りの枠に収まるかを確かめます。金額そのものとは区別します。"},"account":{"name":"アカウント","meaning":"アドレスに対応する残高や送信の通し番号などの状態です。","example":"ここで読むのはノードに保存された状態です。秘密鍵やウォレットのログイン情報ではありません。"},"reorg":{"name":"履歴の差し替え","meaning":"採用していた履歴の一部を外し、別の履歴へ置き換える出来事です。","example":"拡張機能への通知には古い履歴と新しい履歴が入る場合があります。採用されたことと、後から変わらない確定とは区別します。"},"hardfork":{"name":"ルールの切り替え","meaning":"チェーンで使うルールが、指定されたブロック番号や時刻などから切り替わることです。","example":"設定の一覧から、その時点で有効なルールに対応する値を選びます。この関数自体が時計を読み取るわけではありません。"},"base-fee":{"name":"基本手数料の設定","meaning":"基本手数料の変化の計算に使う設定値です。","example":"このコードは計算用の設定を選びます。利用者が支払う最終的な手数料の金額を返す処理ではありません。"},"option":{"name":"Option・Some・None","meaning":"値がある場合と、値がない場合を分ける形です。","example":"Some(値)は値あり、Noneは値なしです。ResultのErrという読取失敗とは別なので、見つからないだけでエラーとは限りません。"},"continue":{"name":"continue・次の繰り返しへ","meaning":"現在の回の残りを飛ばして、繰り返しの次の項目へ進みます。","example":"この関数そのものから戻るreturnとは異なります。"},"ready":{"name":"ready!・準備できるまで待つ","meaning":"PollがPendingなら今のpollからPendingを返し、Readyなら中の値を取り出す記法です。","example":"待機中の間もループで回り続けるという意味ではありません。"},"boolean":{"name":"true・false","meaning":"条件が成り立つかどうかを表す2つの値です。","example":"検査に合格したという結果と、トランザクションの実行結果が成功したことは別に読みます。"}},"contexts":{"tx:rpc":{"intro":"署名済みデータを受け取り、送信の担当処理へ渡して、結果を返す入口です。","terms":["rpc","bytes","hash"],"lines":[{"line":921,"match":"tx: Bytes","label":"入力を受け取る","explanation":"send_raw_transactionという関数が、txという名前でバイト列を受け取ります。&selfはこの処理の対象です。"},{"line":922,"match":"?tx","label":"動作の記録を残す","explanation":"trace!は調査用のログを記録します。?txはログにtxを表示する指定で、失敗を返す演算子ではありません。この行自体はプール追加やブロック取り込みを行いません。"},{"line":923,"match":"send_raw_transaction(self, tx)","label":"次の処理へ渡して待つ","explanation":"受け取ったtxを担当処理へ渡します。.awaitでその結果を待ちます。この一行だけでブロックへ取り込むわけではありません。"},{"line":923,"match":".await?","label":"成功・失敗を返す","explanation":"?は失敗ならエラーを早く返します。成功なら中身を取り出し、外側のOk(...)で成功の結果として返します。ここは?が1個です。"}],"note":"L920は人向けのコメントです。L924の } はこの関数の処理の終わりを示します。L922のログと、L923の結果の受け渡しを分けて読みます。","title":"RPC の入口を読む","source":{"path":"crates/rpc/rpc-eth-api/src/core.rs","start":920,"end":924,"hash":"bed3557bb9602e7337d6c7249cd3e0b53870c86f15ff7896dcf186b648322b9f","code":"    /// Handler for: `eth_sendRawTransaction`\n    async fn send_raw_transaction(&self, tx: Bytes) -> RpcResult<B256> {\n        trace!(target: \"rpc::eth\", ?tx, \"Serving eth_sendRawTransaction\");\n        Ok(EthTransactions::send_raw_transaction(self, tx).await?)\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/core.rs#L920-L924"}},"tx:recover":{"intro":"RPCの受付担当が、署名済みの取引データを読み取り、署名と取引データから送信者のアドレスを求めます。元のデータと読み取り結果を、Reth内部のプール追加処理へ渡します。","terms":["bytes","recover","pool"],"lines":[{"line":86,"match":"tx: Bytes","label":"送信用データを受け取る","explanation":"txは元のバイト列です。この関数全体は後続の追加結果まで待ち、最終的にハッシュまたはエラーを返します。"},{"line":89,"match":"recover_raw_pool_transaction","label":"送信者を復元する","explanation":"元のデータを借りて読み、プールで扱うトランザクションを得ます。失敗したら?でこのasyncブロックから返ります。"},{"line":92,"match":"WithEncoded::new","label":"元データと復元結果を渡す","explanation":"元のバイト列txと、復元したpool_transactionを組にします。"},{"line":94,"match":".await","label":"後続の結果を待つ","explanation":"次の送信処理が終わるのを待ち、その結果をこの関数の結果にします。"}],"note":"","title":"デコードして送信者を復元","source":{"path":"crates/rpc/rpc-eth-api/src/helpers/transaction.rs","start":81,"end":109,"hash":"d066febcf3cc92992a5addaa4c13654202cf6dd200054e0a4f9f37799aafe0ef","code":"    /// Decodes and recovers the transaction and submits it to the pool.\n    ///\n    /// Returns the hash of the transaction.\n    fn send_raw_transaction(\n        &self,\n        tx: Bytes,\n    ) -> impl Future<Output = Result<B256, Self::Error>> + Send {\n        async move {\n            let pool_transaction = self.recover_raw_pool_transaction(&tx)?;\n            self.send_pool_transaction(\n                TransactionOrigin::Local,\n                WithEncoded::new(tx, pool_transaction),\n            )\n            .await\n        }\n    }\n\n    /// Decodes and recovers a raw pool transaction, sharing sender recovery when configured.\n    fn recover_raw_pool_transaction(&self, tx: &[u8]) -> Result<PoolTx<Self::Pool>, Self::Error> {\n        match self.eth_api_settings().sender_recovery_cache.as_ref() {\n            Some(cache) => {\n                <PoolTx<Self::Pool> as PoolTransaction>::recover_raw_transaction_with_cache(\n                    tx, cache,\n                )\n            }\n            None => <PoolTx<Self::Pool> as PoolTransaction>::recover_raw_transaction(tx),\n        }\n        .map_err(Self::Error::from_eth_err)\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/helpers/transaction.rs#L81-L109"}},"tx:submit":{"intro":"設定による分岐を確認し、通常の経路ではプール追加の結果からハッシュを返します。","terms":["pool","hash","bytes"],"lines":[{"line":37,"match":"tx.split()","label":"データを分ける","explanation":"元のバイト列と、プールで扱うトランザクションを取り出します。"},{"line":89,"match":"raw_tx_forwarder","label":"転送する設定を確認する","explanation":"転送先がある場合は別の経路へ進みます。その前には設定に応じたblob sidecarの変換があります。"},{"line":111,"match":"add_pool_transaction","label":"通常経路で追加を待つ","explanation":"転送先がない通常経路で、プールへの追加を依頼して結果を待ちます。"},{"line":113,"match":"Ok(hash)","label":"識別子を返す","explanation":"成功時に取り出したhashを返します。ブロックへの取り込みや確定の通知ではありません。"}],"note":"通常経路はL108・111・113。上の変換・転送の分岐は、必要なときに原文で確かめます。","title":"通常の送信経路を追う","source":{"path":"crates/rpc/rpc/src/eth/helpers/transaction.rs","start":32,"end":114,"hash":"866ae7cc641b85c2d06260abf471913d5741ef54e97838fe4f8f991c6ab7cd17","code":"    async fn send_pool_transaction(\n        &self,\n        origin: reth_transaction_pool::TransactionOrigin,\n        tx: WithEncoded<PoolTx<Self::Pool>>,\n    ) -> Result<B256, Self::Error> {\n        let (tx, mut pool_transaction) = tx.split();\n\n        // Optionally convert legacy blob sidecars to EIP-7594 format when Osaka is active\n        // This is opt-in via --rpc.force-blob-sidecar-upcasting\n        if self.inner.force_blob_sidecar_upcasting() && pool_transaction.is_eip4844() {\n            let EthBlobTransactionSidecar::Present(sidecar) = pool_transaction.take_blob() else {\n                return Err(EthApiError::PoolError(RpcPoolError::Eip4844(\n                    Eip4844PoolTransactionError::MissingEip4844BlobSidecar,\n                )));\n            };\n            let sidecar = sidecar.into_sidecar();\n\n            let sidecar = match sidecar {\n                BlobTransactionSidecarVariant::Eip4844(sidecar) => {\n                    let latest = self\n                        .provider()\n                        .latest_header()?\n                        .ok_or(EthApiError::HeaderNotFound(BlockId::latest()))?;\n                    // Convert to EIP-7594 if next block is Osaka\n                    if self\n                        .provider()\n                        .chain_spec()\n                        .is_osaka_active_at_timestamp(latest.timestamp().saturating_add(12))\n                    {\n                        BlobTransactionSidecarVariant::Eip7594(\n                            self.blob_sidecar_converter().convert(sidecar).await.ok_or_else(\n                                || {\n                                    RpcPoolError::Eip4844(\n                                        Eip4844PoolTransactionError::InvalidEip4844Blob(\n                                            BlobTransactionValidationError::InvalidProof,\n                                        ),\n                                    )\n                                },\n                            )?,\n                        )\n                    } else {\n                        BlobTransactionSidecarVariant::Eip4844(sidecar)\n                    }\n                }\n                sidecar => sidecar,\n            };\n\n            pool_transaction =\n                EthPoolTransaction::try_from_eip4844(pool_transaction.into_consensus(), sidecar)\n                    .ok_or_else(|| {\n                        RpcPoolError::Eip4844(\n                            Eip4844PoolTransactionError::MissingEip4844BlobSidecar,\n                        )\n                    })?;\n        }\n\n        // forward the transaction to the specific endpoint if configured.\n        if let Some(client) = self.raw_tx_forwarder() {\n            tracing::debug!(target: \"rpc::eth\", hash = %pool_transaction.hash(), \"forwarding raw transaction to forwarder\");\n            let rlp_hex = hex::encode_prefixed(&tx);\n\n            // broadcast raw transaction to subscribers if there is any.\n            self.broadcast_raw_transaction(tx);\n\n            let hash =\n                client.request(\"eth_sendRawTransaction\", (rlp_hex,)).await.inspect_err(|err| {\n                    tracing::debug!(target: \"rpc::eth\", %err, hash=% *pool_transaction.hash(), \"failed to forward raw transaction\");\n                }).map_err(EthApiError::other)?;\n\n            // Retain tx in local tx pool after forwarding, for local RPC usage.\n            let _ = self.inner.add_pool_transaction(origin, pool_transaction).await;\n\n            return Ok(hash);\n        }\n\n        // broadcast raw transaction to subscribers if there is any.\n        self.broadcast_raw_transaction(tx);\n\n        let AddedTransactionOutcome { hash, .. } =\n            self.inner.add_pool_transaction(origin, pool_transaction).await?;\n\n        Ok(hash)\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/helpers/transaction.rs#L32-L114"}},"tx:queue":{"intro":"RPCの受付担当が「この取引をプールに追加して」という依頼を内部キューへ渡し、検証・追加が成功したかの返事を待ちます。ブロックへの取り込みを待つ処理ではありません。","terms":["pool","channel","hash"],"lines":[{"line":496,"match":"oneshot::channel()","label":"返答用の経路を作る","explanation":"送信用response_txと受信用response_rxを用意します。この経路で送れる返答は1回です。"},{"line":497,"match":"BatchTxRequest::new","label":"返答口を要求に添える","explanation":"要求を処理する側が返せるよう、送信用の口を要求に添えます。"},{"line":500,"match":".send(request)","label":"要求を渡す","explanation":"内部キューへ要求を渡します。ここでの送信成功だけでは、プール追加の成功は分かりません。"},{"line":503,"match":"response_rx.await??","label":"返答と追加結果を確認する","explanation":"返答を待ち、受信の失敗と、受け取った追加結果の失敗を順に扱います。この箇所には?が2個あります。"}],"note":"","title":"追加要求をチャネルへ送る","source":{"path":"crates/rpc/rpc/src/eth/core.rs","start":489,"end":504,"hash":"fd159467b7670555e1ab3e3663276a187ca277d261c29e6b27f1f7dbb37cd512","code":"    /// Adds an _unvalidated_ transaction into the pool via the transaction batch sender.\n    #[inline]\n    pub async fn add_pool_transaction(\n        &self,\n        origin: reth_transaction_pool::TransactionOrigin,\n        transaction: <N::Pool as TransactionPool>::Transaction,\n    ) -> Result<AddedTransactionOutcome, EthApiError> {\n        let (response_tx, response_rx) = tokio::sync::oneshot::channel();\n        let request = reth_transaction_pool::BatchTxRequest::new(origin, transaction, response_tx);\n\n        self.tx_batch_sender()\n            .send(request)\n            .map_err(|_| reth_rpc_eth_types::EthApiError::BatchTxSendError)?;\n\n        Ok(response_rx.await??)\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/core.rs#L489-L504"}},"tx:batch":{"intro":"届いた要求をまとめてプールへ渡し、それぞれの要求に結果を返します。","terms":["pool","channel"],"lines":[{"line":71,"match":"pool.add_transaction","label":"1件の追加結果を待つ","explanation":"1件を処理するときの呼び出しです。プールでの追加結果を待ちます。"},{"line":72,"match":"response_tx.send","label":"要求した側へ返す","explanation":"その要求の返答口へ、得られた追加結果を送ります。"},{"line":91,"match":"pool.add_transactions","label":"同じ出所の要求をまとめる","explanation":"複数件の追加をまとめて依頼します。続くループでそれぞれに結果を返します。"},{"line":101,"match":"add_transactions_with_origins","label":"出所が異なる場合も扱う","explanation":"各トランザクションの出所を保ってまとめて依頼し、要求ごとの結果を返します。"}],"note":"","tokenHints":{"92":{"for":"for-loop"},"102":{"for":"for-loop"}},"title":"バッチをプールへ引き渡す","source":{"path":"crates/transaction-pool/src/batcher.rs","start":69,"end":105,"hash":"651fd1d5815a1733309eba00584f2a24807211cfcce73c75598fbe3738163262","code":"    async fn process_request(pool: &Pool, req: BatchTxRequest<Pool::Transaction>) {\n        let BatchTxRequest { origin, pool_tx, response_tx } = req;\n        let pool_result = pool.add_transaction(origin, pool_tx).await;\n        let _ = response_tx.send(pool_result);\n    }\n\n    /// Process a batch of transaction requests with per-transaction origins\n    async fn process_batch(pool: &Pool, batch: Vec<BatchTxRequest<Pool::Transaction>>) {\n        if batch.len() == 1 {\n            Self::process_request(pool, batch.into_iter().next().expect(\"batch is not empty\"))\n                .await;\n            return\n        }\n\n        // Same-origin batches can skip the per-transaction origins allocation.\n        let mut batch_iter = batch.iter();\n        if let Some(origin) = batch_iter.next().map(|req| req.origin) &&\n            batch_iter.all(|req| req.origin == origin)\n        {\n            let (transactions, response_txs): (Vec<_>, Vec<_>) =\n                batch.into_iter().map(|req| (req.pool_tx, req.response_tx)).unzip();\n\n            let pool_results = pool.add_transactions(origin, transactions).await;\n            for (response_tx, pool_result) in response_txs.into_iter().zip(pool_results) {\n                let _ = response_tx.send(pool_result);\n            }\n            return\n        }\n\n        let (transactions, response_txs): (Vec<_>, Vec<_>) =\n            batch.into_iter().map(|req| ((req.origin, req.pool_tx), req.response_tx)).unzip();\n\n        let pool_results = pool.add_transactions_with_origins(transactions).await;\n        for (response_tx, pool_result) in response_txs.into_iter().zip(pool_results) {\n            let _ = response_tx.send(pool_result);\n        }\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/batcher.rs#L69-L105"}},"tx:pool":{"intro":"受け取ったトランザクションを検証し、内部プールへ渡して追加の成否を返します。","terms":["pool","hash"],"lines":[{"line":500,"match":"self.validate","label":"検証結果を待つ","explanation":"この要求のトランザクションを検証します。具体的な検証条件は、この抜粋だけでは分かりません。"},{"line":501,"match":"self.pool.add_transactions","label":"内部プールへ渡す","explanation":"検証結果を内部プールへ渡します。検証の結果だけでなく、追加の成否も次に返します。"},{"line":502,"match":"results.pop()","label":"追加結果を返す","explanation":"1件分の結果を取り出して返します。ブロック取り込みやレシートを待つ処理ではありません。"}],"note":"","title":"検証してプールに追加","source":{"path":"crates/transaction-pool/src/lib.rs","start":495,"end":528,"hash":"87582b4a22dc8ac527f8380847cec7d6dcc133c0e12ff281034d3a6252df1443","code":"    async fn add_transaction(\n        &self,\n        origin: TransactionOrigin,\n        transaction: Self::Transaction,\n    ) -> PoolResult<AddedTransactionOutcome> {\n        let tx = self.validate(origin, transaction).await;\n        let mut results = self.pool.add_transactions(origin, std::iter::once(tx));\n        results.pop().expect(\"result length is the same as the input\")\n    }\n\n    async fn add_transactions(\n        &self,\n        origin: TransactionOrigin,\n        transactions: Vec<Self::Transaction>,\n    ) -> Vec<PoolResult<AddedTransactionOutcome>> {\n        if transactions.is_empty() {\n            return Vec::new()\n        }\n        let validated =\n            self.pool.validator().validate_transactions_with_origin(origin, transactions).await;\n        self.pool.add_transactions(origin, validated)\n    }\n\n    async fn add_transactions_with_origins(\n        &self,\n        transactions: Vec<(TransactionOrigin, Self::Transaction)>,\n    ) -> Vec<PoolResult<AddedTransactionOutcome>> {\n        if transactions.is_empty() {\n            return Vec::new()\n        }\n        let origins: Vec<_> = transactions.iter().map(|(origin, _)| *origin).collect();\n        let validated = self.pool.validator().validate_transactions(transactions).await;\n        self.pool.add_transactions_with_origins(origins.into_iter().zip(validated))\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/lib.rs#L495-L528"}},"startup:entry":{"intro":"文字のコマンドを読み、ノードの起動を頼む処理を渡します。起動したあとは、ノードの終了を待ちます。","terms":["cli","node","handle"],"lines":[{"line":40,"match":"Cli::<EthereumChainSpecParser>::parse()","label":"コマンドを読む","explanation":"文字で渡された指示をCli::parse()で読みます。run(...)には、ノードを起動する処理そのものを渡します。"},{"line":42,"match":"let handle","label":"ノードを起動して待つ","explanation":"EthereumNodeを選び、起動の完了を.awaitで待ちます。得られた値をhandleという名前で持ちます。"},{"line":44,"match":"wait_for_node_exit","label":"ノードの終了を待つ","explanation":"起動完了とは別に、動いているノードが終了するのを待ちます。"}],"note":"主な読解箇所はL40・42・44です。L33–38は障害調査に関する準備です。","title":"CLIから起動用の処理を渡す","source":{"path":"bin/reth/src/main.rs","start":33,"end":48,"hash":"fa6e17b75f46bef74d5bcd122d25f92116d1d07ca9e598ccb20b109d1484070c","code":"    reth_cli_util::sigsegv_handler::install();\n\n    // Enable backtraces unless a RUST_BACKTRACE value has already been explicitly provided.\n    if std::env::var_os(\"RUST_BACKTRACE\").is_none() {\n        unsafe { std::env::set_var(\"RUST_BACKTRACE\", \"1\") };\n    }\n\n    if let Err(err) = Cli::<EthereumChainSpecParser>::parse().run(async move |builder, _| {\n        info!(target: \"reth::cli\", \"Launching node\");\n        let handle = builder.node(EthereumNode::default()).launch_with_debug_capabilities().await?;\n\n        handle.wait_for_node_exit().await\n    }) {\n        eprintln!(\"Error: {err:?}\");\n        std::process::exit(1);\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/bin/reth/src/main.rs#L33-L48"}},"startup:dispatch":{"intro":"いくつかあるコマンドからnodeを選び、ノードを動かす処理へ渡します。","terms":["cli","rpc","node"],"lines":[{"line":179,"match":"match cli.command","label":"どのコマンドか分ける","explanation":"入力されたコマンドの種類ごとに、担当する処理を選びます。"},{"line":183,"match":"validate_selection","label":"公開するRPCを確かめる","explanation":"HTTPで公開する操作の選び方を検証します。WebSocket側の指定も続いて確認します。"},{"line":190,"match":"command.execute","label":"起動を担当する処理へ渡す","explanation":"コマンドを実行する処理へ、起動の方法を渡します。"}],"note":"","title":"nodeサブコマンドを選ぶ","source":{"path":"crates/ethereum/cli/src/app.rs","start":159,"end":192,"hash":"11990060943f28db389a5ea613c82038a2522a0aeee93f8dba203f691d6c47ce","code":"/// Run CLI commands with the provided runner, components and launcher.\n/// This is the shared implementation used by both `CliApp` and Cli methods.\npub(crate) fn run_commands_with<C, Ext, Rpc, N, SubCmd>(\n    cli: Cli<C, Ext, Rpc, SubCmd>,\n    runner: CliRunner,\n    components: impl CliComponentsBuilder<N>,\n    launcher: impl AsyncFnOnce(\n        WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,\n        Ext,\n    ) -> Result<()>,\n) -> Result<()>\nwhere\n    C: ChainSpecParser<ChainSpec = N::ChainSpec>,\n    Ext: clap::Args + fmt::Debug,\n    Rpc: RpcModuleValidator,\n    N: CliNodeTypes<Primitives: NodePrimitives<BlockHeader: HeaderMut>, ChainSpec: Hardforks>,\n    SubCmd: ExtendedCommand + Subcommand + fmt::Debug,\n{\n    let rt = runner.runtime();\n\n    match cli.command {\n        Commands::Node(command) => {\n            // Validate RPC modules using the configured validator\n            if let Some(http_api) = &command.rpc.http_api {\n                Rpc::validate_selection(http_api, \"http.api\").map_err(|e| eyre!(\"{e}\"))?;\n            }\n            if let Some(ws_api) = &command.rpc.ws_api {\n                Rpc::validate_selection(ws_api, \"ws.api\").map_err(|e| eyre!(\"{e}\"))?;\n            }\n\n            runner.run_command_until_exit(|ctx| {\n                command.execute(ctx, FnLauncher::new::<C, Ext>(launcher))\n            })\n        }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/ethereum/cli/src/app.rs#L159-L192"}},"startup:supervisor":{"intro":"ノードを動かす処理を進めながら、終了の指示や重大な失敗を監視します。","terms":["cli","thread"],"lines":[{"line":81,"match":"cli_context","label":"実行の準備をする","explanation":"非同期の処理を管理するための情報を用意します。"},{"line":86,"match":"run_until_ctrl_c","label":"終了条件を見ながら進める","explanation":"コマンドを動かし、終了指示や処理の完了を待ちます。外側では重大な失敗も監視します。"},{"line":96,"match":"graceful_shutdown_with_timeout","label":"正常な終了側で後片づけする","explanation":"通常の終了条件なら、動いている処理を終えるよう試みます。"},{"line":99,"match":"runtime_shutdown","label":"実行環境を閉じる","explanation":"最後に非同期の実行環境を閉じ、コマンドの結果を返します。"}],"note":"","title":"起動処理と終了条件を監視する","source":{"path":"crates/cli/runner/src/lib.rs","start":63,"end":102,"hash":"fd8f6cb68f2d5d33c869f37e71f21b1dbd88409975937bde54b10c490523c4d7","code":"    /// Executes the given _async_ command on the tokio runtime until the command future resolves or\n    /// until the process receives a `SIGINT` or `SIGTERM` signal.\n    ///\n    /// Tasks spawned by the command via the [`TaskExecutor`] are shut down and an attempt is made\n    /// to drive their shutdown to completion after the command has finished.\n    pub fn run_command_until_exit<F, E>(\n        self,\n        command: impl FnOnce(CliContext) -> F,\n    ) -> Result<(), E>\n    where\n        F: Future<Output = Result<(), E>>,\n        E: Send\n            + Sync\n            + std::fmt::Display\n            + From<std::io::Error>\n            + From<reth_tasks::PanickedTaskError>\n            + 'static,\n    {\n        let (context, task_manager_handle) = cli_context(&self.runtime);\n\n        // Executes the command until it finished or ctrl-c was fired\n        let command_res = self.runtime.handle().block_on(run_to_completion_or_panic(\n            task_manager_handle,\n            run_until_ctrl_c(command(context)),\n        ));\n\n        if let Err(err) = &command_res {\n            error!(target: \"reth::cli\", %err, \"shutting down due to error\");\n        } else {\n            debug!(target: \"reth::cli\", \"shutting down gracefully\");\n            // after the command has finished or exit signal was received we shutdown the\n            // runtime which fires the shutdown signal to all tasks spawned via the task\n            // executor and awaiting on tasks spawned with graceful shutdown\n            self.runtime.graceful_shutdown_with_timeout(self.config.graceful_shutdown_timeout);\n        }\n\n        runtime_shutdown(self.runtime, true);\n\n        command_res\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/cli/runner/src/lib.rs#L63-L102"}},"startup:database":{"intro":"コマンドの指定を設定へまとめ、データを保存する場所を開いて、ノードの組み立てへ渡します。","terms":["database","node"],"lines":[{"line":189,"match":"NodeConfig","label":"設定をまとめる","explanation":"保存先や通信などの指定を、NodeConfigという設定のまとまりにします。"},{"line":214,"match":"init_db","label":"保存先を開く","explanation":"決めた場所でデータベースを初期化・オープンします。失敗は?で返ります。"},{"line":221,"match":"NodeBuilder::new","label":"組み立ての材料をそろえる","explanation":"設定にデータベースや実行環境を結びつけます。"},{"line":225,"match":"launcher.entrypoint","label":"起動の担当へ渡す","explanation":"そろえた材料を起動処理へ渡し、その結果を待ちます。"}],"note":"","title":"引数を設定に変えてDBを開く","source":{"path":"crates/cli/commands/src/node.rs","start":157,"end":225,"hash":"687cca2e2fe17fd8ce1f54a4c854791e9a615879aede465c96c20bf6ea7b40a3","code":"    pub async fn execute<L>(self, ctx: CliContext, launcher: L) -> eyre::Result<()>\n    where\n        L: Launcher<C, Ext>,\n    {\n        tracing::info!(target: \"reth::cli\", version = ?version::version_metadata().short_version, \"Starting {}\",  version::version_metadata().name_client);\n\n        let Self {\n            datadir,\n            config,\n            chain,\n            metrics,\n            instance,\n            with_unused_ports,\n            network,\n            rpc,\n            txpool,\n            builder,\n            debug,\n            db,\n            dev,\n            pruning,\n            engine,\n            era,\n            static_files,\n            storage,\n            jit,\n            ext,\n        } = self;\n\n        engine.validate()?;\n\n        // set up node config\n        let mut node_config = NodeConfig {\n            datadir,\n            config,\n            chain,\n            metrics,\n            instance,\n            network,\n            rpc,\n            txpool,\n            builder,\n            debug,\n            db,\n            dev,\n            pruning,\n            engine,\n            era,\n            static_files,\n            storage,\n            jit,\n        };\n\n        let data_dir = node_config.datadir();\n        let db_path = data_dir.db();\n\n        tracing::info!(target: \"reth::cli\", path = ?db_path, \"Opening database\");\n        let database = init_db(db_path.clone(), self.db.database_args())?\n            .with_metrics_if(self.db.metrics_enabled());\n\n        if with_unused_ports {\n            node_config = node_config.with_unused_ports();\n        }\n\n        let builder = NodeBuilder::new(node_config)\n            .with_database(database)\n            .with_launch_context(ctx.task_executor);\n\n        launcher.entrypoint(builder, ext).await","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/cli/commands/src/node.rs#L157-L225"}},"startup:context":{"intro":"設定とデータへのアクセスを準備し、チェーンの出発点をそろえて、部品を作る処理へ進みます。","terms":["database","genesis","node"],"lines":[{"line":109,"match":".attach(database.clone())","label":"データベースを結びつける","explanation":"後の処理が保存されたデータを使えるようにします。"},{"line":126,"match":".with_genesis()","label":"チェーンの出発点をそろえる","explanation":"選んだチェーンのgenesisを準備します。"},{"line":140,"match":".with_components","label":"部品を作る処理へ進む","explanation":"設定やデータの準備が済んだら、ノードの各部品を組み立てます。"}],"note":"","title":"設定・provider・genesisを準備する","source":{"path":"crates/node/builder/src/launch/engine.rs","start":101,"end":140,"hash":"67b1d28700a9ebe0a2d0736498bc87779f95b415af2b0573a4537f263a6cf31b","code":"        // setup the launch context\n        let ctx = ctx\n            .with_configured_globals(engine_tree_config.reserved_cpu_cores())\n            // load the toml config\n            .with_loaded_toml_config(config)?\n            // add resolved peers\n            .with_resolved_peers()?\n            // attach the database\n            .attach(database.clone())\n            // ensure certain settings take effect\n            .with_adjusted_configs()\n            // Create the provider factory with the shared overlay manager\n            .with_provider_factory::<_, <CB::Components as NodeComponents<T>>::Evm>(\n                overlay_manager.clone(),\n                rocksdb_provider,\n                disabled_stages,\n            )\n            .await?\n            .inspect(|_| {\n                info!(target: \"reth::cli\", \"Database opened\");\n            })\n            .with_prometheus_server().await?\n            .inspect(|this| {\n                debug!(target: \"reth::cli\", chain=%this.chain_id(), genesis=?this.genesis_hash(), \"Initializing genesis\");\n            })\n            .with_genesis()?\n            .inspect(|this: &LaunchContextWith<Attached<WithConfigs<<T::Types as NodeTypes>::ChainSpec>, _>>| {\n                info!(target: \"reth::cli\", \"\\n{}\", this.chain_spec().display_hardforks());\n                let settings = this.provider_factory().cached_storage_settings();\n                let pruning_mode =\n                    PruneConfigKind::from_config(&this.prune_config(), this.chain_spec().as_ref()).as_str();\n                info!(target: \"reth::cli\", ?settings, ?pruning_mode, \"Loaded storage settings\");\n            })\n            .with_metrics_task()\n            // passing FullNodeTypes as type parameter here so that we can build\n            // later the components.\n            .with_blockchain_db::<T, _>(move |provider_factory| {\n                Ok(BlockchainProvider::new(provider_factory)?)\n            })?\n            .with_components(components_builder, on_component_initialized).await?;","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/node/builder/src/launch/engine.rs#L101-L140"}},"startup:components":{"intro":"実行の設定、プール、通信などを、互いに必要なものを渡しながら組み立てます。","terms":["evm","pool","node"],"lines":[{"line":388,"match":"build_evm","label":"実行の設定を作る","explanation":"Ethereumの処理を実行するための設定を用意します。"},{"line":389,"match":"build_pool","label":"プールを作る","explanation":"実行の設定も渡し、未取り込みのトランザクションを扱う部品を作ります。"},{"line":390,"match":"build_network","label":"通信の部品を作る","explanation":"プールを使う通信の部品を作ります。"},{"line":392,"match":"spawn_payload_builder_service","label":"ブロック候補を作る処理を始める","explanation":"プールと実行の設定を使う、ブロック候補の実行部分を作るサービスを始めます。"}],"note":"","title":"EVM・pool・ネットワークなどを組み立てる","source":{"path":"crates/node/builder/src/components/builder.rs","start":375,"end":403,"hash":"acf421ecf15af4f79502ffe35f6a53011085d8a002c65656cc76732108e62ba7","code":"    async fn build_components(\n        self,\n        context: &BuilderContext<Node>,\n    ) -> eyre::Result<Self::Components> {\n        let Self {\n            pool_builder,\n            payload_builder,\n            network_builder,\n            executor_builder,\n            consensus_builder,\n            _marker,\n        } = self;\n\n        let evm_config = executor_builder.build_evm(context).await?;\n        let pool = pool_builder.build_pool(context, evm_config.clone()).await?;\n        let network = network_builder.build_network(context, pool.clone()).await?;\n        let payload_builder_handle = payload_builder\n            .spawn_payload_builder_service(context, pool.clone(), evm_config.clone())\n            .await?;\n        let consensus = consensus_builder.build_consensus(context).await?;\n\n        Ok(Components {\n            transaction_pool: pool,\n            evm_config,\n            network,\n            payload_builder_handle,\n            consensus,\n        })\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/node/builder/src/components/builder.rs#L375-L403"}},"startup:services":{"intro":"合意側から届く要求と、過去のデータをそろえる処理などをつなぎます。","terms":["engine","database","node"],"lines":[{"line":163,"match":"build_networked_pipeline","label":"過去のデータをそろえる仕組みを作る","explanation":"ネットワークから得るデータを、段階的に扱うpipelineを用意します。"}],"note":"","title":"Engine API・pipeline・treeをつなぐ","source":{"path":"crates/node/builder/src/launch/engine.rs","start":145,"end":266,"hash":"526c2a28152b1255cb3c7765f6f2cb2999aa36e994d9f25bb0fe666d4264225d","code":"        // create pipeline\n        let network_handle = ctx.components().network().clone();\n        let network_client = network_handle.fetch_client().await?;\n        let (consensus_engine_tx, consensus_engine_rx) = unbounded_channel();\n\n        let node_config = ctx.node_config();\n\n        // We always assume that node is syncing after a restart\n        network_handle.update_sync_state(SyncState::Syncing);\n\n        let max_block = ctx.max_block(network_client.clone()).await?;\n\n        let static_file_producer = ctx.static_file_producer();\n        let static_file_producer_events = static_file_producer.lock().events();\n        info!(target: \"reth::cli\", \"StaticFileProducer initialized\");\n\n        let consensus = Arc::new(ctx.components().consensus().clone());\n\n        let pipeline = build_networked_pipeline(\n            &ctx.toml_config().stages,\n            network_client.clone(),\n            consensus.clone(),\n            ctx.provider_factory().clone(),\n            ctx.task_executor(),\n            ctx.sync_metrics_tx(),\n            ctx.prune_config(),\n            max_block,\n            static_file_producer,\n            ctx.components().evm_config().clone(),\n            maybe_exex_manager_handle.clone().unwrap_or_else(ExExManagerHandle::empty),\n            ctx.era_import_source(),\n            disabled_stages,\n        )?;\n\n        // The new engine writes directly to static files. This ensures that they're up to the tip.\n        pipeline.move_to_static_files()?;\n\n        let pipeline_events = pipeline.events();\n\n        let mut pruner_builder = ctx.pruner_builder();\n        if let Some(exex_manager_handle) = &maybe_exex_manager_handle {\n            pruner_builder =\n                pruner_builder.finished_exex_height(exex_manager_handle.finished_height());\n        }\n        let pruner = pruner_builder.build_with_provider_factory(ctx.provider_factory().clone());\n        let pruner_events = pruner.events();\n        info!(target: \"reth::cli\", prune_config=?ctx.prune_config(), \"Pruner initialized\");\n\n        let event_sender = EventSender::default();\n\n        let beacon_engine_handle = ConsensusEngineHandle::new(consensus_engine_tx.clone());\n\n        // extract the jwt secret from the args if possible\n        let jwt_secret = ctx.auth_jwt_secret()?;\n\n        let add_ons_ctx = AddOnsContext {\n            node: ctx.node_adapter().clone(),\n            config: ctx.node_config(),\n            beacon_engine_handle: beacon_engine_handle.clone(),\n            jwt_secret,\n            engine_events: event_sender.clone(),\n            sender_recovery_cache: ctx.sender_recovery_cache().cloned(),\n        };\n        let validator_builder = add_ons.engine_validator_builder();\n\n        // Build the engine validator with all required components\n        let engine_validator = validator_builder\n            .clone()\n            .build_tree_validator(&add_ons_ctx, engine_tree_config.clone(), overlay_manager.clone())\n            .await?;\n\n        // Create the consensus engine stream with optional reorg\n        let reorg_overlay_manager = overlay_manager.clone();\n        let consensus_engine_stream = UnboundedReceiverStream::from(consensus_engine_rx)\n            .maybe_skip_fcu(node_config.debug.skip_fcu)\n            .maybe_skip_new_payload(node_config.debug.skip_new_payload)\n            .maybe_reorg(\n                ctx.blockchain_db().clone(),\n                ctx.components().evm_config().clone(),\n                || async {\n                    validator_builder\n                        .build_tree_validator(\n                            &add_ons_ctx,\n                            engine_tree_config.clone(),\n                            reorg_overlay_manager.clone(),\n                        )\n                        .await\n                },\n                node_config.debug.reorg_frequency,\n                node_config.debug.reorg_depth,\n            )\n            .await?\n            // Store messages _after_ skipping so that `replay-engine` command\n            // would replay only the messages that were observed by the engine\n            // during this run.\n            .maybe_store_messages(node_config.debug.engine_api_store.clone());\n\n        let engine_kind = if ctx.chain_spec().is_optimism() {\n            EngineApiKind::OpStack\n        } else {\n            EngineApiKind::Ethereum\n        };\n\n        let mut orchestrator = EngineOrchestratorBuilder {\n            engine_kind,\n            consensus,\n            client: network_client,\n            incoming_requests: Box::pin(consensus_engine_stream),\n            pipeline,\n            pipeline_task_spawner: ctx.task_executor().clone(),\n            provider: ctx.provider_factory().clone(),\n            blockchain_db: ctx.blockchain_db().clone(),\n            pruner,\n            payload_builder: ctx.components().payload_builder_handle().clone(),\n            payload_validator: engine_validator,\n            overlay_manager,\n            tree_config: engine_tree_config,\n            sync_metrics_tx: ctx.sync_metrics_tx(),\n            evm_config: ctx.components().evm_config().clone(),\n            runtime: ctx.task_executor().clone(),\n        }\n        .build();","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/node/builder/src/launch/engine.rs#L145-L266"}},"startup:orchestrator":{"intro":"入力や停止の指示を待ち、届いた出来事に合う担当へ処理を渡し続けます。","terms":["engine","thread","channel"],"lines":[{"line":332,"match":"loop {","label":"繰り返し処理する","explanation":"入力を一度扱ったあとも、次の入力や停止指示を待てるよう繰り返します。"},{"line":333,"match":"tokio::select!","label":"複数の入力を待つ","explanation":"いくつかある待ち先のうち、準備できたものに応じた処理を進めます。"},{"line":413,"match":"spawn_critical_with_graceful_shutdown_signal","label":"管理される処理として始める","explanation":"終了要求を受けられる非同期タスクとして、ここまで用意した処理を始めます。"}],"note":"","title":"Engineのイベントと終了要求を待つ","source":{"path":"crates/node/builder/src/launch/engine.rs","start":317,"end":413,"hash":"0cf8f72815fa6529f79a88ef9eb36406a3222894f5b1882601e85000e6489692","code":"        let consensus_engine = move |mut on_graceful_shutdown| async move {\n            if let Some(initial_target) = initial_target {\n                debug!(target: \"reth::cli\", %initial_target,  \"start backfill sync\");\n                // network_handle's sync state is already initialized at Syncing\n                orchestrator.start_backfill_sync(initial_target);\n            } else if startup_sync_state_idle {\n                network_handle.update_sync_state(SyncState::Idle);\n            }\n\n            let mut res = Ok(());\n            let mut shutdown_rx = shutdown_rx.fuse();\n\n            // advance the chain and await payloads built locally to add into the engine api\n            // tree handler to prevent re-execution if that block is received as payload from\n            // the CL\n            loop {\n                tokio::select! {\n                    event = orchestrator.next() => {\n                        let Some(event) = event else { break };\n                        debug!(target: \"reth::cli\", \"Event: {event}\");\n                        match event {\n                            ChainEvent::BackfillSyncFinished => {\n                                if terminate_after_backfill {\n                                    debug!(target: \"reth::cli\", \"Terminating after initial backfill\");\n                                    break\n                                }\n                                if startup_sync_state_idle {\n                                    network_handle.update_sync_state(SyncState::Idle);\n                                }\n                            }\n                            ChainEvent::BackfillSyncStarted => {\n                                network_handle.update_sync_state(SyncState::Syncing);\n                            }\n                            ChainEvent::FatalError => {\n                                error!(target: \"reth::cli\", \"Fatal error in consensus engine\");\n                                res = Err(eyre::eyre!(\"Fatal error in consensus engine\"));\n                                break\n                            }\n                            ChainEvent::Handler(ev) => {\n                                if let Some(head) = ev.canonical_header() {\n                                    // Once we're progressing via live sync, we can consider the node is not syncing anymore\n                                    network_handle.update_sync_state(SyncState::Idle);\n                                    let head_block = Head {\n                                        number: head.number(),\n                                        hash: head.hash(),\n                                        difficulty: head.difficulty(),\n                                        timestamp: head.timestamp(),\n                                        total_difficulty: chainspec.final_paris_total_difficulty()\n                                            .filter(|_| chainspec.is_paris_active_at_block(head.number()))\n                                            .unwrap_or_default(),\n                                    };\n                                    network_handle.update_status(head_block);\n\n                                    let updated = BlockRangeUpdate {\n                                        earliest: provider.earliest_block_number().unwrap_or_default(),\n                                        latest: head.number(),\n                                        latest_hash: head.hash(),\n                                    };\n                                    network_handle.update_block_range(updated);\n                                }\n                                event_sender.notify(ev);\n                            }\n                        }\n                    }\n                    Some(payload) = built_payloads.next(), if !built_payloads.is_terminated() => {\n                        if let Some(executed_block) = payload.executed_block() {\n                            debug!(target: \"reth::cli\", block=?executed_block.recovered_block.num_hash(),  \"inserting built payload\");\n                            orchestrator.handler_mut().handler_mut().on_event(EngineApiRequest::InsertExecutedBlock(executed_block).into());\n                        }\n                    }\n                    shutdown_req = &mut shutdown_rx => {\n                        if let Ok(req) = shutdown_req {\n                            debug!(target: \"reth::cli\", \"received engine shutdown request\");\n                            orchestrator.handler_mut().handler_mut().on_event(\n                                FromOrchestrator::Terminate { tx: req.done_tx }.into()\n                            );\n                        }\n                    }\n                    _guard = &mut on_graceful_shutdown => {\n                        // Shutdown signal received.\n                        // Send Terminate so the engine OS thread can exit cleanly before we\n                        // drop the orchestrator.\n                        debug!(target: \"reth::cli\", \"shutdown signal received, terminating engine\");\n                        let (done_tx, done_rx) = oneshot::channel();\n                        orchestrator.handler_mut().handler_mut().on_event(\n                            FromOrchestrator::Terminate { tx: done_tx }.into()\n                        );\n                        let _ = done_rx.await;\n                        break;\n                    }\n                }\n            }\n\n            let _ = exit.send(res);\n        };\n        ctx.task_executor()\n            .spawn_critical_with_graceful_shutdown_signal(\"consensus engine\", consensus_engine);","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/node/builder/src/launch/engine.rs#L317-L413"}},"startup:tree":{"intro":"合意側からの要求や保存の完了を処理します。保存が追いつかないときは、新たな入力より保存を待ちます。","terms":["engine","database","thread"],"lines":[{"line":521,"match":"loop {","label":"入力を処理し続ける","explanation":"この専用スレッド上で、次の出来事を待って処理する流れを繰り返します。"},{"line":564,"match":"wait_for_persistence_event","label":"保存側を待つ場合","explanation":"保存の遅れが条件を満たす場合には、保存側の出来事を待ちます。"},{"line":569,"match":"wait_for_event","label":"通常の入力を待つ場合","explanation":"通常は、Engineの要求など次の出来事を待ちます。"},{"line":572,"match":"match event","label":"出来事の種類で分ける","explanation":"届いた出来事の形をmatchで調べ、Engineの要求、保存完了などに応じた処理を選びます。"},{"line":575,"match":"match self.on_engine_message(msg)","label":"Engineの要求を処理する","explanation":"Engineからの要求を担当処理へ渡します。終了の指示や致命的なエラーなら、このループを終えます。"},{"line":584,"match":"LoopEvent::PersistenceComplete {","label":"保存完了を処理する","explanation":"保存が完了した出来事なら、保存側の結果と処理開始時刻を担当処理へ渡します。"},{"line":591,"match":"LoopEvent::Disconnected =>","label":"経路の切断で終える","explanation":"入力経路が切断された場合はログを残し、この処理を終えます。"}],"note":"","title":"専用スレッドでEngine要求を処理する","source":{"path":"crates/engine/tree/src/tree/mod.rs","start":517,"end":606,"hash":"470b758be1389d3bd7fc7c0177a685ca4eeb2cb9f2339abed411673aba0dab94","code":"    /// Run the engine API handler.\n    ///\n    /// This will block the current thread and process incoming messages.\n    pub fn run(mut self) {\n        loop {\n            // Each iteration has three phases:\n            //\n            // 1. Non-blocking poll for persistence completion. If the background flush already\n            //    landed, absorb the result now so the gap calculation below is fresh.\n            // 2. Decide how to wait for the next event. When the canonical-to-persisted gap beyond\n            //    the in-memory buffer reaches the backpressure threshold we only block on the\n            //    persistence receiver, leaving new engine requests sitting in the unbounded\n            //    upstream channel.\n            // 3. Handle the event (engine message or persistence completion) and kick off a new\n            //    persistence cycle if the threshold is met again.\n            //\n            // The net effect: when the unbuffered persistence gap reaches the threshold, we stop\n            // processing incoming messages and let them queue in the channel. This is only a soft\n            // form of backpressure: it delays replies and, more importantly, prevents executing\n            // further blocks that would pile up in the persistence queue - where each block\n            // carries heavier state (eg. trie updates) than the raw payload sitting in the engine\n            // channel.\n            //\n            // Standard Ethereum CLs won't truly back off - the engine API has no\n            // backpressure semantics, and CLs typically timeout after ≈8s and resend - so\n            // this cannot prevent the incoming channel from growing under sustained load.\n            // But it shifts the bottleneck to the lighter-weight incoming queue rather than\n            // the costlier persistence pipeline. Other clients that respect reply latency\n            // can treat the delayed responses as a signal to chill out.\n            match self.try_poll_persistence() {\n                Ok(true) => {\n                    if let Err(err) = self.advance_persistence() {\n                        error!(target: \"engine::tree\", %err, \"Advancing persistence failed\");\n                        return\n                    }\n                    continue;\n                }\n                Ok(false) => {}\n                Err(err) => {\n                    error!(target: \"engine::tree\", %err, \"Polling persistence failed\");\n                    return\n                }\n            }\n\n            let event = if self.should_backpressure() {\n                self.metrics.engine.backpressure_active.set(1.0);\n                let stall_start = Instant::now();\n                let event = self.wait_for_persistence_event();\n                self.metrics.engine.backpressure_stall_duration.record(stall_start.elapsed());\n                event\n            } else {\n                self.metrics.engine.backpressure_active.set(0.0);\n                self.wait_for_event()\n            };\n\n            match event {\n                LoopEvent::EngineMessage(msg) => {\n                    debug!(target: \"engine::tree\", %msg, \"received new engine message\");\n                    match self.on_engine_message(msg) {\n                        Ok(ops::ControlFlow::Break(())) => return,\n                        Ok(ops::ControlFlow::Continue(())) => {}\n                        Err(fatal) => {\n                            error!(target: \"engine::tree\", %fatal, \"insert block fatal error\");\n                            return\n                        }\n                    }\n                }\n                LoopEvent::PersistenceComplete { result, start_time } => {\n                    if let Err(err) = self.on_persistence_complete(result, start_time) {\n                        error!(target: \"engine::tree\", %err, \"Persistence complete handling failed\");\n                        return\n                    }\n                }\n                LoopEvent::PayloadBuildFinished => {}\n                LoopEvent::Disconnected => {\n                    error!(target: \"engine::tree\", \"Channel disconnected\");\n                    return\n                }\n            }\n\n            // Always check if we need to trigger new persistence after any event:\n            // - After engine messages: new blocks may have been inserted that exceed the\n            //   persistence threshold\n            // - After persistence completion: we can now persist more blocks if needed\n            if let Err(err) = self.advance_persistence() {\n                error!(target: \"engine::tree\", %err, \"Advancing persistence failed\");\n                return\n            }\n        }\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/engine/tree/src/tree/mod.rs#L517-L606"}},"startup:network":{"intro":"ノード間の通信や内部からの要求を進めます。すぐに進められなければ、ほかの処理へ実行を譲ります。","terms":["node","poll","thread"],"lines":[{"line":1134,"match":"Future for NetworkManager","label":"通信の処理をFutureとして実装する","explanation":"impl ... for ... は型への操作の実装です。NetworkManagerをFutureとして進めるため、後ろでpollを定義しています。このforは繰り返しではありません。"},{"line":1137,"match":"fn poll","label":"進められるかを確かめる入口","explanation":"実行環境がこのFutureを進めるときに呼ぶ処理です。"},{"line":1176,"match":"from_handle_rx.poll_next_unpin","label":"内部からの要求を取り出す","explanation":"ノード内部の別の部品から届いた要求を処理します。"},{"line":1187,"match":"this.swarm.poll_next_unpin","label":"通信からの出来事を取り出す","explanation":"ネットワーク側で起きた出来事を処理します。"},{"line":1202,"match":"Poll::Pending","label":"いったん実行を譲る","explanation":"今すぐ返す最終結果はないと実行環境へ伝えます。"}],"note":"","tokenHints":{"1134":{"for":"for-implementation"}},"title":"ネットワークの入出力をpollで進める","source":{"path":"crates/net/network/src/manager.rs","start":1134,"end":1203,"hash":"b125fa83aa6585d42fcde364a7c001aa47ba86621c72b14261274814b3768664","code":"impl<N: NetworkPrimitives> Future for NetworkManager<N> {\n    type Output = ();\n\n    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {\n        let start = Instant::now();\n        let mut poll_durations = NetworkManagerPollDurations::default();\n\n        let this = self.get_mut();\n\n        // poll new block imports (expected to be a noop for POS)\n        while let Poll::Ready(outcome) = this.block_import.poll(cx) {\n            this.on_block_import_result(outcome);\n        }\n\n        // These loops drive the entire state of network and does a lot of work. Under heavy load\n        // (many messages/events), data may arrive faster than it can be processed (incoming\n        // messages/requests -> events), and it is possible that more data has already arrived by\n        // the time an internal event is processed. Which could turn this loop into a busy loop.\n        // Without yielding back to the executor, it can starve other tasks waiting on that\n        // executor to execute them, or drive underlying resources To prevent this, we\n        // preemptively return control when the `budget` is exhausted. The value itself is chosen\n        // somewhat arbitrarily, it is high enough so the swarm can make meaningful progress but\n        // low enough that this loop does not starve other tasks for too long. If the budget is\n        // exhausted we manually yield back control to the (coop) scheduler. This manual yield\n        // point should prevent situations where polling appears to be frozen. See also\n        // <https://tokio.rs/blog/2020-04-preemption> And tokio's docs on cooperative scheduling\n        // <https://docs.rs/tokio/latest/tokio/task/#cooperative-scheduling>\n        //\n        // Testing has shown that this loop naturally reaches the pending state within 1-5\n        // iterations in << 100µs in most cases. On average it requires ~50µs, which is inside the\n        // range of what's recommended as rule of thumb.\n        // <https://ryhl.io/blog/async-what-is-blocking/>\n\n        // process incoming messages from a handle (`TransactionsManager` has one)\n        //\n        // will only be closed if the channel was deliberately closed since we always have an\n        // instance of `NetworkHandle`\n        let start_network_handle = Instant::now();\n        let maybe_more_handle_messages = poll_nested_stream_with_budget!(\n            \"net\",\n            \"Network message channel\",\n            DEFAULT_BUDGET_TRY_DRAIN_NETWORK_HANDLE_CHANNEL,\n            this.from_handle_rx.poll_next_unpin(cx),\n            |msg| this.on_handle_message(msg),\n            error!(\"Network channel closed\");\n        );\n        poll_durations.acc_network_handle = start_network_handle.elapsed();\n\n        // process incoming messages from the network\n        let maybe_more_swarm_events = poll_nested_stream_with_budget!(\n            \"net\",\n            \"Swarm events stream\",\n            DEFAULT_BUDGET_TRY_DRAIN_SWARM,\n            this.swarm.poll_next_unpin(cx),\n            |event| this.on_swarm_event(event),\n        );\n        poll_durations.acc_swarm =\n            start_network_handle.elapsed() - poll_durations.acc_network_handle;\n\n        // all streams are fully drained and import futures pending\n        if maybe_more_handle_messages || maybe_more_swarm_events {\n            // make sure we're woken up again\n            cx.waker().wake_by_ref();\n            return Poll::Pending\n        }\n\n        this.update_poll_metrics(start, poll_durations);\n\n        Poll::Pending\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/net/network/src/manager.rs#L1134-L1203"}},"startup:backfill":{"intro":"過去のブロックなどをまとめてそろえる必要があるとき、段階的な同期を始めて結果を待ちます。","terms":["engine","channel","poll"],"lines":[{"line":143,"match":"pending_pipeline_target.take()","label":"同期の目標を取り出す","explanation":"待機中のpipelineの同期目標を取り出します。take()の結果はOptionです。目標がSomeなら中身を取り出し、Noneなら ? によってこの関数からNoneを返します。"},{"line":150,"match":"pipeline.run_as_fut","label":"同期処理を動かして待つ","explanation":"目標を渡して処理を進め、終わるのを待ちます。"},{"line":151,"match":"tx.send(result)","label":"結果を返す","explanation":"完了した結果を、専用の返答経路で受け取り側へ送ります。"},{"line":174,"match":"PipelineState::Idle","label":"次に備えて待機状態へ戻す","explanation":"受け取ったpipelineを保持し直し、次の要求に備えます。"}],"note":"","tokenHints":{"143":{"?":"option-question"}},"title":"必要なときだけ段階的同期を走らせる","source":{"path":"crates/engine/tree/src/backfill.rs","start":123,"end":183,"hash":"b04ca743e3203651126f4c80adf62b084637154e66662ef9ec358b82d9bf1c6b","code":"    /// Sets a new target to sync the pipeline to.\n    ///\n    /// But ensures the target is not the zero hash.\n    fn set_pipeline_sync_target(&mut self, target: PipelineTarget) {\n        if target.sync_target().is_some_and(|target| target.is_zero()) {\n            trace!(\n                target: \"consensus::engine::sync\",\n                \"Pipeline target cannot be zero hash.\"\n            );\n            // precaution to never sync to the zero hash\n            return\n        }\n        self.pending_pipeline_target = Some(target);\n    }\n\n    /// This will spawn the pipeline if it is idle and a target is set or if the pipeline is set to\n    /// run continuously.\n    fn try_spawn_pipeline(&mut self) -> Option<BackfillEvent> {\n        match &mut self.pipeline_state {\n            PipelineState::Idle(pipeline) => {\n                let target = self.pending_pipeline_target.take()?;\n                let (tx, rx) = oneshot::channel();\n\n                let pipeline = pipeline.take().expect(\"exists\");\n                self.pipeline_task_spawner.spawn_critical_blocking_task(\n                    \"pipeline task\",\n                    async move {\n                        let result = pipeline.run_as_fut(Some(target)).await;\n                        let _ = tx.send(result);\n                    },\n                );\n                self.pipeline_state = PipelineState::Running(rx);\n\n                Some(BackfillEvent::Started(target))\n            }\n            PipelineState::Running(_) => None,\n        }\n    }\n\n    /// Advances the pipeline state.\n    ///\n    /// This checks for the result in the channel, or returns pending if the pipeline is idle.\n    fn poll_pipeline(&mut self, cx: &mut Context<'_>) -> Poll<BackfillEvent> {\n        let res = match self.pipeline_state {\n            PipelineState::Idle(_) => return Poll::Pending,\n            PipelineState::Running(ref mut fut) => {\n                ready!(fut.poll_unpin(cx))\n            }\n        };\n        let ev = match res {\n            Ok((pipeline, result)) => {\n                self.pipeline_state = PipelineState::Idle(Some(Box::new(pipeline)));\n                BackfillEvent::Finished(result)\n            }\n            Err(why) => {\n                // failed to receive the pipeline\n                BackfillEvent::TaskDropped(why.to_string())\n            }\n        };\n        Poll::Ready(ev)\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/engine/tree/src/backfill.rs#L123-L183"}},"area:sync":{"intro":"不足する記録をそろえる仕事を段階ごとに進めます。結果に応じて進捗を更新し、問題があれば巻き戻します。","terms":["stage","unwind","block"],"lines":[{"line":223,"match":"fn run_loop","label":"一巡の入口","explanation":"受け取るものは、段階の一覧や保存先、進捗を持つselfです。結果は次に進むための制御情報かエラーです。"},{"line":227,"match":"for stage_index","label":"段階を順に選ぶ","explanation":"段階の一覧を、先頭から一つずつ選んで処理します。"},{"line":232,"match":"execute_stage_to_completion","label":"その段階の完了を待つ","explanation":"前の段階の進捗を渡して完了を待ちます。?が付くため、失敗ならこの関数からエラーを返します。"},{"line":243,"match":"ControlFlow::Unwind","label":"巻き戻しの指示を扱う","explanation":"巻き戻しを行い、その指示を呼び出し元へ返します。通常の進捗更新とは分けています。"},{"line":258,"match":"Ok(self.progress.next_ctrl())","label":"一巡の結果を返す","explanation":"全段階を終えた場合は、進捗に対応する次の制御情報を成功として返します。"}],"note":"各段階の具体的な取得・実行条件は別の実装です。この範囲だけで全同期モードを説明したものではありません。","tokenHints":{"227":{"for":"for-loop"}},"title":"同期の段階を順に進める","source":{"path":"crates/stages/api/src/pipeline/mod.rs","start":213,"end":259,"hash":"c5de87c96b9f8224d1151587ff4e51f03914b720f7ab0f160d91955ce685099a","code":"    /// execution of each stage, it proceeds to commit it to the database.\n    ///\n    /// If any stage is unsuccessful at execution, we proceed to\n    /// unwind. This will undo the progress across the entire pipeline\n    /// up to the block that caused the error.\n    ///\n    /// Returns the control flow after it ran the pipeline.\n    /// This will be [`ControlFlow::Continue`] or [`ControlFlow::NoProgress`] of the _last_ stage in\n    /// the pipeline (for example the `Finish` stage). Or [`ControlFlow::Unwind`] of the stage\n    /// that caused the unwind.\n    pub async fn run_loop(&mut self) -> Result<ControlFlow, PipelineError> {\n        self.move_to_static_files()?;\n\n        let mut previous_stage = None;\n        for stage_index in 0..self.stages.len() {\n            let stage = &self.stages[stage_index];\n            let stage_id = stage.id();\n\n            trace!(target: \"sync::pipeline\", stage = %stage_id, \"Executing stage\");\n            let next = self.execute_stage_to_completion(previous_stage, stage_index).await?;\n\n            trace!(target: \"sync::pipeline\", stage = %stage_id, ?next, \"Completed stage\");\n\n            match next {\n                ControlFlow::NoProgress { block_number } => {\n                    if let Some(block_number) = block_number {\n                        self.progress.update(block_number);\n                    }\n                }\n                ControlFlow::Continue { block_number } => self.progress.update(block_number),\n                ControlFlow::Unwind { target, bad_block } => {\n                    self.unwind(target, Some(bad_block.block.number))?;\n                    return Ok(ControlFlow::Unwind { target, bad_block })\n                }\n            }\n\n            previous_stage = Some(\n                self.provider_factory\n                    .provider()?\n                    .get_stage_checkpoint(stage_id)?\n                    .unwrap_or_default()\n                    .block_number,\n            );\n        }\n\n        Ok(self.progress.next_ctrl())\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/stages/api/src/pipeline/mod.rs#L213-L259"}},"area:execution":{"intro":"受け取ったブロックのトランザクションを順に実行し、実行結果を返します。前後に必要な状態変更も行います。","terms":["block","state","receipt"],"lines":[{"line":596,"match":"fn execute_one","label":"ブロックを受け取る入口","explanation":"blockという引数で、送信者が復元されたトランザクションを含むブロックを受け取ります。成功時の結果か実行エラーを返します。"},{"line":614,"match":"apply_pre_execution_changes","label":"実行前の変更を行う","explanation":"ブロック内の要求を処理する前に必要な変更を行います。失敗なら?でエラーを返します。"},{"line":620,"match":"for tx","label":"要求を一つずつ取り出す","explanation":"ブロック内のトランザクションを、順に一つずつ取り出します。"},{"line":621,"match":"execute_transaction(tx)?","label":"一件を実行する","explanation":"取り出した要求を実行します。失敗したときは後続へ進まず、エラーを返します。"},{"line":627,"match":"apply_post_execution_changes","label":"実行後の変更と結果","explanation":"必要な実行後の変更を行い、resultに実行結果を持ちます。"},{"line":631,"match":"Ok(result)","label":"実行結果を返す","explanation":"実行結果を成功として返します。保存先へのcommitをこの行で実行しているわけではありません。"}],"note":"BALがあるかどうかの分岐も含みますが、個別のEVM命令や検証ルールの全てをこの範囲で解説してはいません。","tokenHints":{"620":{"for":"for-loop"}},"title":"ブロック内のトランザクションを実行する","source":{"path":"crates/evm/evm/src/execute.rs","start":596,"end":632,"hash":"e2d250e6445fc04f2a8f22e4d5102947f67d11d71c631a31163d16e72854316f","code":"    fn execute_one(\n        &mut self,\n        block: &RecoveredBlock<<Self::Primitives as NodePrimitives>::Block>,\n    ) -> Result<BlockExecutionResult<<Self::Primitives as NodePrimitives>::Receipt>, Self::Error>\n    {\n        let mut executor = self\n            .strategy_factory\n            .executor_for_block(&mut self.db, block)\n            .map_err(BlockExecutionError::other)?;\n\n        let has_bal = block.header().block_access_list_hash().is_some();\n\n        if has_bal {\n            executor.evm_mut().db_mut().bal_state.bal_builder = Some(Bal::new());\n        } else {\n            executor.evm_mut().db_mut().bal_state.bal_builder = None;\n        }\n\n        executor.apply_pre_execution_changes()?;\n\n        if has_bal {\n            executor.evm_mut().db_mut().bump_bal_index();\n        }\n\n        for tx in block.transactions_recovered() {\n            executor.execute_transaction(tx)?;\n            if has_bal {\n                executor.evm_mut().db_mut().bump_bal_index();\n            }\n        }\n\n        let result = executor.apply_post_execution_changes()?;\n\n        self.db.merge_transitions(BundleRetention::Reverts);\n\n        Ok(result)\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/evm/evm/src/execute.rs#L596-L632"}},"area:payload":{"intro":"ブロック候補を作るための引数と、プール・状態参照などの部品を担当処理へ渡し、その結果を返します。","terms":["payload","pool","state"],"lines":[{"line":90,"match":"fn try_build","label":"候補作成の入口","explanation":"argsとして候補作成のための引数を受け取ります。Resultは候補作成の結果かエラーを表します。"},{"line":94,"match":"default_ethereum_payload","label":"候補を作る担当へ渡す","explanation":"EVMの設定、状態を読む部品、プール、作成設定と引数を渡します。"},{"line":100,"match":"best_transactions_with_attributes","label":"プールから選ぶ操作を渡す","explanation":"条件に応じたトランザクションを選ぶ操作も、担当処理へ渡します。"},{"line":101,"match":")","label":"担当処理の結果を返す","explanation":"呼び出しが最後の式なので、そのResultをこの関数の結果として返します。"}],"note":"この入口だけでは、採用する取引の全条件や候補の差し替え条件は確認できません。候補作成は履歴の採用・確定とは別です。","title":"ブロック候補を作る処理へ渡す","source":{"path":"crates/ethereum/payload/src/lib.rs","start":90,"end":102,"hash":"45364bcf43e4e47358bf9dd021f81c1f95141dcb934aa10ae75ccca4d39add33","code":"    fn try_build(\n        &self,\n        args: BuildArguments<EthPayloadAttributes, EthBuiltPayload>,\n    ) -> Result<BuildOutcome<EthBuiltPayload>, PayloadBuilderError> {\n        default_ethereum_payload(\n            self.evm_config.clone(),\n            self.client.clone(),\n            self.pool.clone(),\n            self.builder_config.clone(),\n            args,\n            |attributes| self.pool.best_transactions_with_attributes(attributes),\n        )\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/ethereum/payload/src/lib.rs#L90-L102"}},"area:storage":{"intro":"書き込み用の部品が持つ変更を、保存先へ確定します。通常の保存と巻き戻しの場合で処理を分けます。","terms":["database","state","unwind"],"lines":[{"line":3965,"match":"fn commit","label":"保存を確定する入口","explanation":"selfが、書き込み中のデータベース操作や保存先を保持しています。成功時は追加データなし、失敗時はエラーを返します。"},{"line":3966,"match":"if self.static_file_provider","label":"保存方法を分ける","explanation":"巻き戻しが必要な場合はcommit_unwindへ進み、通常の場合はelse側へ進みます。"},{"line":3973,"match":"finalize()?","label":"静的ファイルの処理を確定","explanation":"通常の場合は、先に静的ファイル側の処理を確定します。失敗なら?でエラーを返します。"},{"line":3979,"match":"commit_batch(batch)?","label":"待機中のバッチを確定","explanation":"待機しているRocksDBの書き込みのまとまりを、一つずつ確定します。"},{"line":3984,"match":"self.tx.commit()?","label":"DBの変更を確定","explanation":"データベースの書き込み操作を確定します。"},{"line":3990,"match":"Ok(())","label":"保存の成功を返す","explanation":"ここまで成功したら、追加データを持たない成功結果を返します。"}],"note":"保存先への書き込みの確定を読む範囲です。変更データの作成や、複数保存先をまたぐ全体の原子性をこの抜粋だけで保証しません。","tokenHints":{"3978":{"for":"for-loop"}},"title":"保存の変更を確定する","source":{"path":"crates/storage/provider/src/providers/database/provider.rs","start":3965,"end":3991,"hash":"8ed93abedc6226be38c12f9bcfe98931d303a7a686637031e668236af8b06d62","code":"    fn commit(self) -> ProviderResult<()> {\n        if self.static_file_provider.has_unwind_queued() || self.commit_order.is_unwind() {\n            self.commit_unwind()?;\n        } else {\n            // Normal path: finalize() will call sync_all() if not already synced\n            let mut timings = metrics::CommitTimings::default();\n\n            let start = Instant::now();\n            self.static_file_provider.finalize()?;\n            timings.sf = start.elapsed();\n\n            let start = Instant::now();\n            let batches = std::mem::take(&mut *self.pending_rocksdb_batches.lock());\n            for batch in batches {\n                self.rocksdb_provider.commit_batch(batch)?;\n            }\n            timings.rocksdb = start.elapsed();\n\n            let start = Instant::now();\n            self.tx.commit()?;\n            timings.mdbx = start.elapsed();\n\n            self.metrics.record_commit(&timings);\n        }\n\n        Ok(())\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/storage/provider/src/providers/database/provider.rs#L3965-L3991"}},"area:extension":{"intro":"通知を受け渡す経路に空きができるのを待ち、出来事の通知を送ります。","terms":["notification","channel","block"],"lines":[{"line":613,"match":"fn send_async","label":"通知の入口","explanation":"通知の出所sourceと通知データnotificationを受け取ります。成功か送信エラーを返します。"},{"line":618,"match":"self.ready().await","label":"経路の空きを待つ","explanation":"通知を受け付けられる状態になるまで待ちます。待っている間は、ほかの処理を進められます。"},{"line":619,"match":"self.exex_tx.send","label":"通知を経路へ渡す","explanation":"出所と通知をまとめて渡し、その送信結果を返します。経路の受け手が利用できなければ送信エラーになり得ます。"}],"note":"この成功は通知経路への送信結果です。拡張機能の処理完了や、ブロックの確定完了を保証するものではありません。","title":"拡張機能へ通知を渡す","source":{"path":"crates/exex/exex/src/manager.rs","start":609,"end":620,"hash":"21c3b8f32db8b3f1356204e9ec5726e9d601eaca036bfa3d2e663fd2475cd3de","code":"    /// Asynchronously send a notification over the channel to all execution extensions.\n    ///\n    /// The returned future resolves when the notification has been delivered. If there is no\n    /// capacity in the channel, the future will wait.\n    pub async fn send_async(\n        &mut self,\n        source: ExExNotificationSource,\n        notification: ExExNotification<N>,\n    ) -> Result<(), SendError<(ExExNotificationSource, ExExNotification<N>)>> {\n        self.ready().await;\n        self.exex_tx.send((source, notification))\n    }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/exex/exex/src/manager.rs#L609-L620"}},"area:foundation":{"intro":"mainnet用に組み込まれた最初の状態のJSONを読み、チェーンの設定を組み立てます。","terms":["chain-config","genesis","json"],"lines":[{"line":115,"match":"pub static MAINNET","label":"mainnet設定を用意する","explanation":"LazyLockは、この値が必要になったときに初期化するための仕組みです。組み込みのmainnet設定を用意します。"},{"line":116,"match":"serde_json::from_str","label":"組み込まれたJSONを読む","explanation":"入力はinclude_str!で取り込むmainnet.jsonの文字列です。"},{"line":117,"match":".expect","label":"読み取れなければ停止する","explanation":"読み取りに失敗したときは、指定メッセージでpanicを起こします。RPCの呼び出し元へResultで返す処理とは異なります。"},{"line":119,"match":"let mut spec = ChainSpec","label":"設定を組み立てる","explanation":"読み取ったgenesisや、どのルール変更を使うかなどをChainSpecへまとめます。"},{"line":142,"match":"spec.into()","label":"共有する設定値へ変換","explanation":"組み立てた設定を、外側のMAINNETが保持する共有用の形へ変換して返します。"}],"note":"これは組み込みmainnet用の設定です。利用者が指定した任意ファイルを解析する処理や、接続・同期の完了を示すコードではありません。","title":"組み込みのチェーン設定を読む","source":{"path":"crates/chainspec/src/spec.rs","start":114,"end":143,"hash":"c76ea04a3faac76d238f6f222c7e4fe703a378e17e12e60ed02368b840f27f58","code":"/// The Ethereum mainnet spec\npub static MAINNET: LazyLock<Arc<ChainSpec>> = LazyLock::new(|| {\n    let genesis = serde_json::from_str(include_str!(\"../res/genesis/mainnet.json\"))\n        .expect(\"Can't deserialize Mainnet genesis json\");\n    let hardforks = EthereumHardfork::mainnet().into();\n    let mut spec = ChainSpec {\n        chain: Chain::mainnet(),\n        genesis_header: SealedHeader::new(\n            make_genesis_header(&genesis, &hardforks),\n            MAINNET_GENESIS_HASH,\n        ),\n        genesis,\n        // <https://etherscan.io/block/15537394>\n        paris_block_and_final_difficulty: Some((\n            MAINNET_PARIS_BLOCK,\n            U256::from(58_750_003_716_598_352_816_469u128),\n        )),\n        hardforks,\n        // https://etherscan.io/tx/0xe75fb554e433e03763a1560646ee22dcb74e5274b34c5ad644e7c0f619a7e1d0\n        deposit_contract: Some(MAINNET_DEPOSIT_CONTRACT),\n        base_fee_params: BaseFeeParamsKind::Constant(BaseFeeParams::ethereum()),\n        prune_delete_limit: MAINNET_PRUNE_DELETE_LIMIT,\n        blob_params: BlobScheduleBlobParams::default().with_scheduled([\n            (mainnet::MAINNET_BPO1_TIMESTAMP, BlobParams::bpo1()),\n            (mainnet::MAINNET_BPO2_TIMESTAMP, BlobParams::bpo2()),\n        ]),\n    };\n    spec.genesis.config.dao_fork_support = true;\n    spec.into()\n});","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/chainspec/src/spec.rs#L114-L143"}},"area:pool-validation":{"intro":"プールの検証条件の一例です。要求にチェーンIDがある場合は、ノード側のチェーンIDと比べます。","terms":["chain-id","pool"],"lines":[{"line":593,"match":"if let Some(chain_id)","label":"番号がある場合を調べる","explanation":"要求にチェーンIDが含まれている場合、その値を取り出します。全ての要求にこの項目があると決め付けてはいません。"},{"line":594,"match":"chain_id != self.chain_id()","label":"ノード側の番号と比較","explanation":"要求の番号と、設定されたノード側の番号が違うか調べます。"},{"line":596,"match":"return Err","label":"違えば検証エラーを返す","explanation":"異なるネットワーク向けの要求なら、ChainIdMismatchというエラーを返して、この検証処理を終えます。"}],"note":"validate_stateless内の一条件だけの抜粋です。ガス・手数料・残高など他の検証条件や、検証全体の成功箇所はこの範囲の外です。","title":"送信先のチェーンIDを比べる","source":{"path":"crates/transaction-pool/src/validate/eth.rs","start":592,"end":598,"hash":"8e6b9d2e8ec6ae08600fc9e6bd1ed2f68d160aa36bbf0d5a582451d3c4f9c1ac","code":"        // Checks for chainid\n        if let Some(chain_id) = transaction.chain_id() &&\n            chain_id != self.chain_id()\n        {\n            return Err(InvalidTransactionError::ChainIdMismatch.into())\n        }\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/validate/eth.rs#L592-L598"}},"area:node-exit":{"intro":"終了を表す内部処理を進め、結果がまだなければ待機し、用意できた成功・エラーを返します。","terms":["node","await","ready","option","result"],"lines":[{"line":39,"match":"if let Some(rx)","label":"内部処理があるか確かめる","explanation":"Someなら待機対象を取り出し、ない場合は後ろのelseでPendingを返します。"},{"line":40,"match":"match ready!","label":"まだ結果がなければ待つ","explanation":"ready!は内部処理がPendingなら、このpollもPendingで戻します。結果があれば成功・失敗を分けます。"},{"line":42,"match":"this.consensus_engine_fut.take();","label":"成功した待機対象を取り除く","explanation":"成功した後、保持していた内部処理を取り除きます。"},{"line":45,"match":"Err(err) =>","label":"失敗をそのまま返す","explanation":"内部処理のエラーをReady(Err(err))として返します。成功に変える処理ではありません。"}],"note":"終了の要求を送る処理ではありません。内部処理がない場合もPendingで、起動成功や同期完了とは区別します。","tokenHints":{"34":{"for":"for-implementation"}},"title":"終了を待つ間、成功と失敗をどう返す？","source":{"path":"crates/node/core/src/exit.rs","start":34,"end":51,"hash":"ebf7213c538babcaeb8db341934e038b5112fac76ee0bc7e7f07810013d7bebc","code":"impl Future for NodeExitFuture {\n    type Output = eyre::Result<()>;\n\n    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {\n        let this = self.get_mut();\n        if let Some(rx) = this.consensus_engine_fut.as_mut() {\n            match ready!(rx.poll_unpin(cx)) {\n                Ok(_) => {\n                    this.consensus_engine_fut.take();\n                    Poll::Ready(Ok(()))\n                }\n                Err(err) => Poll::Ready(Err(err)),\n            }\n        } else {\n            Poll::Pending\n        }\n    }\n}","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/node/core/src/exit.rs#L34-L51"}},"area:rpc-recovery":{"intro":"送信用のデータを読み解き、署名から送信者を求め、両方を組にして返します。","terms":["bytes","recover","option","result"],"lines":[{"line":752,"match":"decode_raw_transaction::<T>(tx)?","label":"まずデータを読み解く","explanation":"読み取りが失敗した場合は?で現在の関数からエラーを返します。"},{"line":754,"match":"Some(cache) =>","label":"キャッシュがあれば使う","explanation":"キャッシュが設定されている場合はcache.recoverへ渡します。"},{"line":755,"match":"None =>","label":"なければ直接復元を試す","explanation":"キャッシュがないこと自体をエラーにせず、transaction.try_recover()を呼びます。"},{"line":757,"match":"map_err(|_|","label":"復元の失敗をエラーにする","explanation":"復元失敗をInvalidTransactionSignatureへ変換し、?で返します。"},{"line":758,"match":"Ok(Recovered::","label":"復元した送信者とデータを返す","explanation":"ここまで成功したデータと送信者を組にして返します。"}],"note":"秘密鍵を取り出す処理でも、プール追加やブロックへの取り込みでもありません。キャッシュがなくても直接の復元を試みます。","title":"受信したデータから送信者を求めるには？","source":{"path":"crates/rpc/rpc-eth-api/src/helpers/transaction.rs","start":750,"end":760,"hash":"03aefeb423d3fff38a2750477cee38730e61c055dd8802693ef568cc2432cca8","code":"    /// Decodes and recovers a raw transaction, sharing sender recovery when configured.\n    fn recover_raw_transaction<T: SignedTransaction>(&self, tx: &[u8]) -> EthResult<Recovered<T>> {\n        let transaction = decode_raw_transaction::<T>(tx)?;\n        let signer = match self.eth_api_settings().sender_recovery_cache.as_ref() {\n            Some(cache) => cache.recover(&transaction),\n            None => transaction.try_recover(),\n        }\n        .map_err(|_| EthApiError::InvalidTransactionSignature)?;\n        Ok(Recovered::new_unchecked(transaction, signer))\n    }\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/helpers/transaction.rs#L750-L760"}},"area:pool-balance":{"intro":"必要額と送信者の残高を比べ、検査が有効で残高が不足していればエラーを返します。","terms":["pool","account","result","if"],"lines":[{"line":790,"match":"let cost =","label":"必要額を取得する","explanation":"トランザクションのcostを読みます。costの内部計算式はこの抜粋の外です。"},{"line":792,"match":"if !self.disable_balance_check","label":"検査が有効で、残高より大きいか","explanation":"!は否定、&&は両方を満たす条件です。検査無効なら残高不足の分岐へ入りません。"},{"line":794,"match":"return Err(InvalidTransactionError::InsufficientFunds","label":"不足のエラーを返す","explanation":"実際の残高と必要額をエラーに入れて返します。"},{"line":799,"match":"Ok(())","label":"この検査の成功を返す","explanation":"不足分岐に入らなければ、この関数は成功を返します。"}],"note":"Okはこの残高検査を通ったことだけです。無効設定の場合もOkとなり、他の検査・実行・確定の成功は示しません。","title":"残高が足りない要求は、いつ失敗になる？","source":{"path":"crates/transaction-pool/src/validate/eth.rs","start":783,"end":801,"hash":"f866a8645febe255f2b629d59278403ba631b955696eb0fc1437281d45928a7d","code":"\n    /// Ensures the sender has sufficient account balance.\n    pub fn validate_sender_balance(\n        &self,\n        transaction: &Tx,\n        sender: &Account,\n    ) -> Result<(), InvalidPoolTransactionError> {\n        let cost = transaction.cost();\n\n        if !self.disable_balance_check && cost > &sender.balance {\n            let expected = *cost;\n            return Err(InvalidTransactionError::InsufficientFunds(\n                GotExpected { got: sender.balance, expected }.into(),\n            )\n            .into())\n        }\n        Ok(())\n    }\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/validate/eth.rs#L783-L801"}},"area:network-reputation":{"intro":"相手と評価変更の種類を見て、変更の不要・免除・上限調整を経て評価を更新する入口です。","terms":["peer","option","result","if"],"lines":[{"line":549,"match":"if rep.is_reset()","label":"リセットか通常の変更か分ける","explanation":"リセットならNone、通常は変更量を計算します。変更量が0なら戻ります。"},{"line":559,"match":"if let Some(peer)","label":"登録された相手を取り出す","explanation":"相手が一覧にない場合は、後ろのelseで何も変更せず戻ります。"},{"line":561,"match":"if peer.is_trusted()","label":"信頼済み・固定の相手を区別する","explanation":"どちらかの場合、次の特定の種類について変更を免除します。"},{"line":567,"match":"ReputationChangeKind::Timeout","label":"通信条件による変更を免除する","explanation":"Timeoutなど列挙された種類ならreturnし、評価へ変更を適用しません。"},{"line":579,"match":"peer.apply_reputation","label":"調整後の変更を適用する","explanation":"免除されない変更は、必要なら上限を調整してから相手に適用します。"}],"note":"この抜粋はoutcomeを得るまでです。結果に応じた遮断など後続の処理全体は含みません。信頼済みでも全ての変更が免除されるわけではありません。","title":"通信相手の評価変更を、いつ省略する？","source":{"path":"crates/net/network/src/peers.rs","start":546,"end":585,"hash":"328b551bd002f7d8f169b7f7c409fcc5e30501d2f81530381de17c5488dd3944","code":"    pub(crate) fn apply_reputation_change(&mut self, peer_id: &PeerId, rep: ReputationChangeKind) {\n        trace!(target: \"net::peers\", ?peer_id, reputation=?rep, \"applying reputation change\");\n\n        let reputation_change = if rep.is_reset() {\n            None\n        } else {\n            let reputation_change = self.reputation_weights.change(rep).as_i32();\n            if reputation_change == 0 {\n                return\n            }\n            Some(reputation_change)\n        };\n\n        let outcome = if let Some(peer) = self.peers.get_mut(peer_id) {\n            if let Some(mut reputation_change) = reputation_change {\n                if peer.is_trusted() || peer.is_static() {\n                    // exempt trusted and static peers from reputation slashing for\n                    if matches!(\n                        rep,\n                        ReputationChangeKind::Dropped |\n                            ReputationChangeKind::BadAnnouncement |\n                            ReputationChangeKind::Timeout |\n                            ReputationChangeKind::AlreadySeenTransaction\n                    ) {\n                        return\n                    }\n\n                    // also be less strict with the reputation slashing for trusted peers\n                    if reputation_change < MAX_TRUSTED_PEER_REPUTATION_CHANGE {\n                        // this caps the reputation change to the maximum allowed for trusted peers\n                        reputation_change = MAX_TRUSTED_PEER_REPUTATION_CHANGE;\n                    }\n                }\n                peer.apply_reputation(reputation_change, rep)\n            } else {\n                peer.reset_reputation()\n            }\n        } else {\n            return\n        };","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/net/network/src/peers.rs#L546-L585"}},"area:sync-unwind":{"intro":"保存済み進捗と目標を確認し、同期した順と逆に段階を見て、目標より手前の段階を飛ばします。","terms":["stage","unwind","database","continue"],"lines":[{"line":317,"match":"ensure_unwind_target_unpruned","label":"戻れる範囲か確かめる","explanation":"削除設定とチェックポイントから目標を確認し、失敗なら?でエラーを返します。"},{"line":320,"match":"let unwind_pipeline =","label":"同期と逆の順で段階を見る","explanation":"iter_mut().rev()で、実行した順と逆に各段階を取り出します。"},{"line":335,"match":"if checkpoint.block_number < to","label":"目標より手前なら対象外","explanation":"現在の進捗が目標の番号より小さい場合だけ、次のスキップ処理に入ります。"},{"line":342,"match":"self.event_sender.notify(PipelineEvent::Skipped","label":"飛ばしたことを通知する","explanation":"この段階は飛ばすと通知してから、continueで次の段階へ進みます。"}],"note":"進捗が目標より小さい段階はSkipped通知後にcontinueします。等しい場合の処理や実際の段階の巻き戻し・保存は後続の範囲です。","tokenHints":{"329":{"for":"for-loop"}},"title":"巻き戻す段階は、どの順に選ぶ？","source":{"path":"crates/stages/api/src/pipeline/mod.rs","start":302,"end":346,"hash":"d142b6232a76ffd0f4dd005b8acfee11a7bcd6e8e2c19b5a28a86e1490c591bd","code":"    /// If the unwind is due to a bad block the number of that block should be specified.\n    pub fn unwind(\n        &mut self,\n        to: BlockNumber,\n        bad_block: Option<BlockNumber>,\n    ) -> Result<(), PipelineError> {\n        // Add validation before starting unwind\n        let (latest_block, prune_modes, checkpoints) = {\n            let provider = self.provider_factory.provider()?;\n            (\n                provider.last_block_number()?,\n                provider.prune_modes_ref().clone(),\n                provider.get_prune_checkpoints()?,\n            )\n        };\n        prune_modes.ensure_unwind_target_unpruned(latest_block, to, &checkpoints)?;\n\n        // Unwind stages in reverse order of execution\n        let unwind_pipeline = self.stages.iter_mut().rev();\n\n        // Legacy Engine: This prevents a race condition in which the `StaticFileProducer` could\n        // attempt to proceed with a finalized block which has been unwinded\n        let _locked_sf_producer = self.static_file_producer.lock();\n\n        let mut provider_rw =\n            self.provider_factory.unwind_provider_rw()?.disable_long_read_transaction_safety();\n\n        for stage in unwind_pipeline {\n            let stage_id = stage.id();\n            let span = info_span!(\"Unwinding\", stage = %stage_id);\n            let _enter = span.enter();\n\n            let mut checkpoint = provider_rw.get_stage_checkpoint(stage_id)?.unwrap_or_default();\n            if checkpoint.block_number < to {\n                debug!(\n                    target: \"sync::pipeline\",\n                    from = %checkpoint.block_number,\n                    %to,\n                    \"Unwind point too far for stage\"\n                );\n                self.event_sender.notify(PipelineEvent::Skipped { stage_id });\n\n                continue\n            }\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/stages/api/src/pipeline/mod.rs#L302-L346"}},"area:engine-timestamp":{"intro":"候補を作るための属性の時刻を、現在のヘッダーの時刻と比べます。","terms":["engine","block","result","if"],"lines":[{"line":256,"match":"attr: &Types::","label":"候補作成の属性を受け取る","explanation":"属性と比較先ヘッダーを借りて検査します。"},{"line":259,"match":"if attr.timestamp() <=","label":"同じ時刻も失敗にする","explanation":"<=は小さいか等しいという条件なので、同じ時刻も失敗の分岐に入ります。"},{"line":260,"match":"return Err(","label":"時刻のエラーを返す","explanation":"条件に入ればInvalidTimestampを返して関数を終えます。"},{"line":262,"match":"Ok(())","label":"この時刻検査を通す","explanation":"条件に入らない、大きい時刻の場合は成功を返します。"}],"note":"この関数は時刻の条件だけを検査します。Okは候補の作成完了や、履歴の採用・確定を意味しません。","title":"次の候補の時刻が同じだったら、どうなる？","source":{"path":"crates/engine/primitives/src/lib.rs","start":254,"end":264,"hash":"e654d1df933b4ad9d99d53578439a26297eb6cee35755981561bce6971bf190d","code":"    fn validate_payload_attributes_against_header(\n        &self,\n        attr: &Types::PayloadAttributes,\n        header: &<Self::Block as Block>::Header,\n    ) -> Result<(), InvalidPayloadAttributesError> {\n        if attr.timestamp() <= header.timestamp() {\n            return Err(InvalidPayloadAttributesError::InvalidTimestamp);\n        }\n        Ok(())\n    }\n}","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/engine/primitives/src/lib.rs#L254-L264"}},"area:execution-receipt":{"intro":"実行結果から、種類・成功印・累積ガス・ログを持つレシートを組み立てます。","terms":["evm","receipt","gas","boolean"],"lines":[{"line":17,"match":"let ReceiptBuilderCtx","label":"渡された情報を取り出す","explanation":"ctxから種類、実行結果、累積ガスを取り出します。"},{"line":18,"match":"        Receipt {","label":"レシートを組み立てる","explanation":"この値が関数の戻り値になります。Errを返す関数宣言ではありません。"},{"line":22,"match":"success: result.is_success()","label":"実行成功かを印にする","explanation":"実行が失敗ならfalseをsuccess欄へ入れます。それでもレシートの値を組み立てます。"},{"line":24,"match":"logs: result.into_logs()","label":"実行結果のログを移す","explanation":"累積ガスとともに、実行結果から取り出したログをレシートへ入れます。"}],"note":"この関数は実行済みの結果を記録へ移します。実行失敗ならsuccessがfalseになり、レシートの作成自体をErrにする分岐はありません。保存や確定も別です。","tokenHints":{"12":{"for":"for-implementation"}},"title":"失敗した実行も、レシートには残る？","source":{"path":"crates/ethereum/evm/src/receipt.rs","start":12,"end":27,"hash":"299af6fbea744e4558ceb00f1a1941518efdfaf3849e3cccb595440e7820844e","code":"impl ReceiptBuilder for RethReceiptBuilder {\n    type Transaction = TransactionSigned;\n    type Receipt = Receipt;\n\n    fn build_receipt<E: Evm>(&self, ctx: ReceiptBuilderCtx<'_, TxType, E>) -> Self::Receipt {\n        let ReceiptBuilderCtx { tx_type, result, cumulative_gas_used, .. } = ctx;\n        Receipt {\n            tx_type,\n            // Success flag was added in `EIP-658: Embedding transaction status code in\n            // receipts`.\n            success: result.is_success(),\n            cumulative_gas_used,\n            logs: result.into_logs(),\n        }\n    }\n}","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/ethereum/evm/src/receipt.rs#L12-L27"}},"area:payload-cancel":{"intro":"要求が残りのガス枠に収まるかを判定し、超過なら飛ばし、中止されていれば候補作成を終えます。","terms":["payload","gas","continue","result"],"lines":[{"line":265,"match":"let exceeds_gas_limit","label":"ルールに応じて残りの枠と比べる","explanation":"Amsterdamが有効かで計算を分け、上限が残りの枠を超える場合にSomeを作ります。"},{"line":287,"match":"best_txs.mark_invalid(","label":"入らない要求に印を付ける","explanation":"ガス枠を超えた要求は候補のイテレーターで無効にし、依存する要求も選ばないようにします。"},{"line":294,"match":"            continue","label":"次の要求へ進む","explanation":"この回の残りを飛ばします。関数全体からCancelledを返すのとは異なります。"},{"line":299,"match":"return Ok(BuildOutcome::Cancelled)","label":"中止なら候補作成を終える","explanation":"この中止検査まで進んで真なら、Cancelledという結果を成功の形で返します。中止をErrとしては返しません。"}],"note":"無効の印は候補選択のイテレーターに付けます。プール全体から削除したとまでは言えません。continueすると、この回の中止検査へは進みません。","title":"候補に入れない要求と、候補作成の中止は同じ？","source":{"path":"crates/ethereum/payload/src/lib.rs","start":265,"end":300,"hash":"51ff71fac90e873f0fa0f32e9c58e5d9e70e970a9952dbb2e9a6f934241cab7c","code":"        let exceeds_gas_limit = if is_amsterdam {\n            let regular_available_gas = block_gas_limit.saturating_sub(block_regular_gas_used);\n            let state_available_gas = block_gas_limit.saturating_sub(block_state_gas_used);\n            let regular_tx_gas_limit = pool_tx.gas_limit().min(tx_gas_limit_cap);\n\n            if regular_tx_gas_limit > regular_available_gas {\n                Some((regular_tx_gas_limit, regular_available_gas))\n            } else if pool_tx.gas_limit() > state_available_gas {\n                Some((pool_tx.gas_limit(), state_available_gas))\n            } else {\n                None\n            }\n        } else {\n            let block_available_gas = block_gas_limit.saturating_sub(cumulative_tx_gas_used);\n            (pool_tx.gas_limit() > block_available_gas)\n                .then_some((pool_tx.gas_limit(), block_available_gas))\n        };\n\n        if let Some((transaction_gas_limit, block_available_gas)) = exceeds_gas_limit {\n            // we can't fit this transaction into the block, so we need to mark it as invalid\n            // which also removes all dependent transaction from the iterator before we can\n            // continue\n            best_txs.mark_invalid(\n                &pool_tx,\n                InvalidPoolTransactionError::ExceedsGasLimit(\n                    transaction_gas_limit,\n                    block_available_gas,\n                ),\n            );\n            continue\n        }\n\n        // check if the job was cancelled, if so we can exit early\n        if cancel.is_cancelled() {\n            return Ok(BuildOutcome::Cancelled)\n        }","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/ethereum/payload/src/lib.rs#L265-L300"}},"area:storage-account":{"intro":"保存形式の設定を見て、アドレスそのものか、そのハッシュをキーに現在のアカウントを読みます。","terms":["database","account","hash","option","result"],"lines":[{"line":74,"match":"if self.0.cached_storage_settings()","label":"保存形式で分ける","explanation":"ハッシュ形式が有効なら、次のハッシュしたアドレスを使う分岐へ入ります。"},{"line":75,"match":"let hashed_address","label":"アドレスをハッシュする","explanation":"keccak256(address)で求めた値を、HashedAccountsの検索キーにします。"},{"line":77,"match":"get_by_encoded_key::<tables::HashedAccounts>","label":"ハッシュ形式の表から読む","explanation":"取得結果のOptionはそのまま保ち、map_errでエラーの種類を合わせます。"},{"line":80,"match":"self.tx().get_by_encoded_key::<tables::PlainAccountState>","label":"通常形式ではアドレスで読む","explanation":"else側は元のaddressをキーにPlainAccountStateから読みます。"}],"note":"読取専用の入口で、残高を増減したり送信を実行する処理ではありません。Noneは値なしで、DBの読取失敗とは別です。","title":"アドレスから読むとき、値なしとエラーをどう分ける？","source":{"path":"crates/storage/provider/src/providers/state/latest.rs","start":69,"end":84,"hash":"6ef8fd3d3c9f1d215d3ad00ad86b0bf602aa20098b5031c67818b6642c8f5327","code":"impl<Provider: DBProvider + StorageSettingsCache> AccountReader\n    for LatestStateProviderRef<'_, Provider>\n{\n    /// Get basic account information.\n    fn basic_account(&self, address: &Address) -> ProviderResult<Option<Account>> {\n        if self.0.cached_storage_settings().use_hashed_state() {\n            let hashed_address = alloy_primitives::keccak256(address);\n            self.tx()\n                .get_by_encoded_key::<tables::HashedAccounts>(&hashed_address)\n                .map_err(Into::into)\n        } else {\n            self.tx().get_by_encoded_key::<tables::PlainAccountState>(address).map_err(Into::into)\n        }\n    }\n}\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/storage/provider/src/providers/state/latest.rs#L69-L84"}},"area:extension-reorg":{"intro":"通知の種類に応じて、新しく採用した履歴と、外した古い履歴を別々に取り出します。","terms":["notification","reorg","option","block"],"lines":[{"line":33,"match":"pub fn committed_chain","label":"新しく採用した履歴を取り出す","explanation":"採用・差し替えならnewをSomeで返し、取り消しだけならNoneです。"},{"line":36,"match":"Self::ChainReverted { .. } => None","label":"取り消しだけなら新履歴はない","explanation":"committed_chainでは取り消した履歴を新履歴としては返しません。"},{"line":42,"match":"pub fn reverted_chain","label":"外した古い履歴を取り出す","explanation":"差し替え・取り消しならoldをSomeで返し、採用だけならNoneです。"},{"line":45,"match":"Self::ChainCommitted { .. } => None","label":"採用だけなら旧履歴はない","explanation":"reverted_chainでは採用だけの通知から古い履歴を取り出せません。"}],"note":"履歴を取り出す関数で、差し替え自体を実行する処理ではありません。採用通知と履歴の確定も別です。cloneはArcの共有参照を複製します。","title":"履歴の差し替え通知から、新旧どちらを取れる？","source":{"path":"crates/exex/types/src/notification.rs","start":10,"end":48,"hash":"bcde49e579c27ab3c716d4ab713353ff9fb679aa5e9b642ab9296badff728e2f","code":"pub enum ExExNotification<N: NodePrimitives = reth_chain_state::EthPrimitives> {\n    /// Chain got committed without a reorg, and only the new chain is returned.\n    ChainCommitted {\n        /// The new chain after commit.\n        new: Arc<Chain<N>>,\n    },\n    /// Chain got reorged, and both the old and the new chains are returned.\n    ChainReorged {\n        /// The old chain before reorg.\n        old: Arc<Chain<N>>,\n        /// The new chain after reorg.\n        new: Arc<Chain<N>>,\n    },\n    /// Chain got reverted, and only the old chain is returned.\n    ChainReverted {\n        /// The old chain before reversion.\n        old: Arc<Chain<N>>,\n    },\n}\n\nimpl<N: NodePrimitives> ExExNotification<N> {\n    /// Returns the committed chain from the [`Self::ChainCommitted`] and [`Self::ChainReorged`]\n    /// variants, if any.\n    pub fn committed_chain(&self) -> Option<Arc<Chain<N>>> {\n        match self {\n            Self::ChainCommitted { new } | Self::ChainReorged { old: _, new } => Some(new.clone()),\n            Self::ChainReverted { .. } => None,\n        }\n    }\n\n    /// Returns the reverted chain from the [`Self::ChainReorged`] and [`Self::ChainReverted`]\n    /// variants, if any.\n    pub fn reverted_chain(&self) -> Option<Arc<Chain<N>>> {\n        match self {\n            Self::ChainReorged { old, new: _ } | Self::ChainReverted { old } => Some(old.clone()),\n            Self::ChainCommitted { .. } => None,\n        }\n    }\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/exex/types/src/notification.rs#L10-L48"}},"area:foundation-fee":{"intro":"固定設定ならそのまま返し、可変設定なら指定された時刻で有効なルールの設定を選びます。","terms":["hardfork","base-fee","option","return"],"lines":[{"line":541,"match":"BaseFeeParamsKind::Constant","label":"固定設定ならそのまま返す","explanation":"時刻で選び直さず、保持しているbf_paramsを返します。"},{"line":546,"match":"for (fork, params)","label":"可変一覧を逆順に見る","explanation":"設定の一覧を逆順にたどります。有効なルールがあるか次のifで確かめます。"},{"line":548,"match":"return *params","label":"最初に有効な設定を返す","explanation":"指定時刻で有効なら、その設定を返して関数を終えます。"},{"line":552,"match":"bf_params.first()","label":"該当なしや空一覧を扱う","explanation":"有効なものがなくても一覧があれば先頭を使い、一覧が空ならBaseFeeParams::ethereumを使います。"}],"note":"可変一覧を逆順に見て最初に有効なものを返します。該当なしなら一覧の先頭、空一覧ならEthereumの既定設定です。この関数は現在時刻の取得や手数料額の計算をしません。","tokenHints":{"546":{"for":"for-loop"}},"title":"時刻で使う手数料の設定を、どう選ぶ？","source":{"path":"crates/chainspec/src/spec.rs","start":538,"end":556,"hash":"5a8bb53a0f98e277a334ff58744a183276518fcc3dda2409205db13d2a645a00","code":"    /// Get the [`BaseFeeParams`] for the chain at the given timestamp.\n    pub fn base_fee_params_at_timestamp(&self, timestamp: u64) -> BaseFeeParams {\n        match self.base_fee_params {\n            BaseFeeParamsKind::Constant(bf_params) => bf_params,\n            BaseFeeParamsKind::Variable(ForkBaseFeeParams(ref bf_params)) => {\n                // Walk through the base fee params configuration in reverse order, and return the\n                // first one that corresponds to a hardfork that is active at the\n                // given timestamp.\n                for (fork, params) in bf_params.iter().rev() {\n                    if self.hardforks.is_fork_active_at_timestamp(fork.clone(), timestamp) {\n                        return *params\n                    }\n                }\n\n                bf_params.first().map(|(_, params)| *params).unwrap_or_else(BaseFeeParams::ethereum)\n            }\n        }\n    }\n","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/chainspec/src/spec.rs#L538-L556"}},"area:block-link":{"intro":"ブロックの見出しにある、前を指すハッシュと番号のつながりを確かめます。","terms":["block","hash","result","option"],"lines":[{"line":294,"match":"if parent.hash() != header.parent_hash()","label":"前を指すハッシュを比べる","explanation":"このブロックが前のブロックとして指す値を、渡された親のハッシュと比べます。異なればParentHashMismatchを返します。"},{"line":300,"match":"let Some(parent_number)","label":"親の番号に1を足せるか確かめる","explanation":"checked_add(1)は番号に1を足せた場合Some、数の上限を超える場合Noneです。足せない場合はelseで番号のエラーを返します。"},{"line":309,"match":"if parent_number != header.number()","label":"番号が一つ先か確かめる","explanation":"親の番号に1を足した値と、このブロックの番号を比べます。一致しなければParentBlockNumberMismatchを返します。"},{"line":316,"match":"    Ok(())","label":"この検査の成功を返す","explanation":"ここまでの条件を満たせば追加データのない成功を返します。採用や確定まで終わったという意味ではありません。"}],"note":"この関数は渡された親とのつながりを検査する一部です。共有の履歴を選ぶことや確定を決める処理、ブロック検証の全条件を示すものではありません。","title":"前のブロックとのつながりを検証する","source":{"path":"crates/consensus/common/src/validation.rs","start":290,"end":317,"hash":"d95e4fad6597ea43c131a28d05884247cff4680aa1bbdf374a849bb4f34322f1","code":"pub fn validate_against_parent_hash_number<H: BlockHeader>(\n    header: &H,\n    parent: &SealedHeader<H>,\n) -> Result<(), ConsensusError> {\n    if parent.hash() != header.parent_hash() {\n        return Err(ConsensusError::ParentHashMismatch(\n            GotExpected { got: header.parent_hash(), expected: parent.hash() }.into(),\n        ))\n    }\n\n    let Some(parent_number) = parent.number().checked_add(1) else {\n        // parent block already reached the maximum\n        return Err(ConsensusError::ParentBlockNumberMismatch {\n            parent_block_number: parent.number(),\n            block_number: u64::MAX,\n        })\n    };\n\n    // Parent number is consistent.\n    if parent_number != header.number() {\n        return Err(ConsensusError::ParentBlockNumberMismatch {\n            parent_block_number: parent.number(),\n            block_number: header.number(),\n        })\n    }\n\n    Ok(())\n}","url":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/consensus/common/src/validation.rs#L290-L317"}}},"lessonLinks":[{"lesson":"blockchain","context":"area:block-link","title":"前のブロックとのつながりを確かめる","why":"「ブロックが前を指してつながる」という説明を、ハッシュと番号の比較から確かめられます。","scope":"Rethでの検証の一例です。どの履歴を共有の記録として採用・確定するかは、この関数では決めません。","area":"engine","crate":{"id":"crates/consensus/common/Cargo.toml","name":"reth-consensus-common","hash":"b09d97a64fcbb36385a855ea7932beac8c7c4d3a71f9aa4357fa17cdb646e4ab","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/crates/consensus/common"}},{"lesson":"ethereum","context":"area:execution","title":"ブロック内の要求を実行する","why":"トランザクションを順に実行し、前後の状態変更と結果をまとめる入口を確かめられます。","scope":"状態更新を進める入口です。送金やEVM命令の内部、保存・履歴の確定の全処理は別にあります。","area":"execution","crate":{"id":"crates/evm/evm/Cargo.toml","name":"reth-evm","hash":"1954b5e967f32f19c86734a3231bf3ffbed2a358fab3489b4f477d03b7c4dba6","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/crates/evm/evm"}},{"lesson":"rpc","context":"tx:rpc","title":"署名済みデータを受け取るRPCの入口","why":"RPCの窓口が受け取るバイト列と、返すハッシュ・エラーを原文で区別できます。","scope":"ここでは送信要求の入口を読みます。RPCメソッド全体や、ブロックへの取り込み完了を示すものではありません。","area":"rpc","crate":{"id":"crates/rpc/rpc-eth-api/Cargo.toml","name":"reth-rpc-eth-api","hash":"b89291737f93ddc3b2e3f9972d7d55064e7bfaaea530f6df6310cf78b06c0c6b","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api"}},{"lesson":"reth","context":"startup:tree","title":"合意側から届く要求を実行側で扱う","why":"Rethの内部で要求を受け取り、担当の処理へ渡す境界を確かめられます。","scope":"実行側の処理です。コンセンサスクライアントの履歴選択や確定のアルゴリズム本体ではありません。","area":"engine","crate":{"id":"crates/engine/tree/Cargo.toml","name":"reth-engine-tree","hash":"4f7837ff880fc68416ee7a344ad95307f6923c1c4425167772daca599f908568","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/crates/engine/tree"}},{"lesson":"send","context":"tx:recover","title":"受信データを読み、送信者を復元する","why":"送信用のデータが、送信者を確かめられる形になって次の処理へ渡る箇所を読めます。","scope":"復元と受け渡しの範囲です。キューへの送信、プールへの追加、取り込みの完了は分けて読みます。","area":"rpc","crate":{"id":"crates/rpc/rpc-eth-api/Cargo.toml","name":"reth-rpc-eth-api","hash":"b89291737f93ddc3b2e3f9972d7d55064e7bfaaea530f6df6310cf78b06c0c6b","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api"}},{"lesson":"startup","context":"startup:entry","title":"起動の完了とノードの終了を待つ","why":"起動処理を渡す箇所と、稼働したノードの終了を待つ箇所を比べられます。","scope":"CLIの入口です。すべての部品の組み立てや、稼働中のイベント処理は呼び出し先にあります。","area":"node","crate":{"id":"bin/reth/Cargo.toml","name":"reth","hash":"e3e0ae4895b60e79287234e8169821e27e1ad7421a9e1127ac57042fb35f3439","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/bin/reth"}},{"lesson":"reading","context":"tx:rpc","title":"最初の問いをRPCの短いコードで確かめる","why":"入力・出力・失敗という読み方を、実際の短い関数で試せます。","scope":"この関数が担当処理へ渡すところまでを読みます。リポジトリ全体の理解とは分けて記録します。","area":"rpc","crate":{"id":"crates/rpc/rpc-eth-api/Cargo.toml","name":"reth-rpc-eth-api","hash":"b89291737f93ddc3b2e3f9972d7d55064e7bfaaea530f6df6310cf78b06c0c6b","url":"https://github.com/paradigmxyz/reth/tree/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api"}}],"areaReadings":[{"area":"node","title":"ノードの起動","question":"ノードは、いつ起動を終えて何を待つ？","role":"文字のコマンドを読み、ノードを起動する処理を渡し、終了を待ちます。","input":"コマンドラインで指定された起動方法や設定。","output":"起動後のhandleでノードの終了を待ち、CLI全体の実行結果を返します。","boundary":"L42は起動の完了待ち、L44は終了待ちです。起動完了でプロセス全体が終了するわけではありません。","context":"startup:entry","followup":{"context":"area:node-exit","question":"終了を待つ間、成功と失敗をどう返す？","role":"終了を表す内部処理を進め、結果がまだなければ待機し、用意できた成功・エラーを返します。","input":"内部処理を保持するselfと、再び実行してもらうための通知先cx。","output":"Poll::Readyの成功かエラー、またはPoll::Pending。","boundary":"終了の要求を送る処理ではありません。内部処理がない場合もPendingで、起動成功や同期完了とは区別します。","selfCheck":"待っている内部処理がエラーを返した場合、この待機処理は成功になるか。根拠行と結果を説明する"}},{"area":"rpc","title":"RPCの入口","question":"送信要求の入口は何を受け取り、何を返す？","role":"アプリから届いた署名済みデータを担当処理へ渡します。","input":"署名済みトランザクションのバイト列tx: Bytes。","output":"成功なら識別用のハッシュ、失敗ならRPCのエラー。","boundary":"返答のハッシュはブロックへの取り込みや確定の完了を意味しません。ログの?txと、失敗を返す.await?を分けて読みます。","context":"tx:rpc","followup":{"context":"area:rpc-recovery","question":"受信したデータから送信者を求めるには？","role":"送信用のデータを読み解き、署名から送信者を求め、両方を組にして返します。","input":"txという名前で借りたバイト列と、復元キャッシュの設定。","output":"署名済みデータと送信者の組Recovered、またはEthApiError。","boundary":"秘密鍵を取り出す処理でも、プール追加やブロックへの取り込みでもありません。キャッシュがなくても直接の復元を試みます。","selfCheck":"復元用キャッシュが未設定の場合と、署名の復元に失敗した場合をそれぞれ説明する"}},{"area":"pool","title":"プールの検証と追加","question":"プールに追加する前に、何を確かめる？","role":"トランザクションを検証してから、内部プールへ渡して追加結果を返します。","input":"トランザクションと、その要求がどこから来たかを示すorigin。","output":"1件分のプール追加結果。検証や追加に失敗する場合もあります。","boundary":"下の追加入口だけでは検証の全条件は分かりません。「検証条件の一例」でチェーンID不一致のエラーを原文で確認できます。プール追加はブロックの確定とは別です。","context":"tx:pool","extraContext":"area:pool-validation","followup":{"context":"area:pool-balance","question":"残高が足りない要求は、いつ失敗になる？","role":"必要額と送信者の残高を比べ、検査が有効で残高が不足していればエラーを返します。","input":"トランザクション、送信者の状態、残高検査を無効にする設定。","output":"検査に通ればOk(())、不足ならInsufficientFunds。","boundary":"Okはこの残高検査を通ったことだけです。無効設定の場合もOkとなり、他の検査・実行・確定の成功は示しません。","selfCheck":"必要額が残高より大きいとき、検査が有効の場合と無効の場合でどう変わるか説明する"}},{"area":"network","title":"通信の待機","question":"通信の出来事がない間は、どう待つ？","role":"内部の要求やネットワークの出来事を取り出して処理します。","input":"ノード内部からの要求と、ネットワーク側の出来事。","output":"今すぐ返す最終結果がなければPoll::Pending。","boundary":"仕事が残る場合も実行を譲り、再び起こしてもらうよう通知します。停止や同期待ちの完了を意味しません。","context":"startup:network","followup":{"context":"area:network-reputation","question":"通信相手の評価変更を、いつ省略する？","role":"相手と評価変更の種類を見て、変更の不要・免除・上限調整を経て評価を更新する入口です。","input":"相手の識別子peer_idと変更の種類rep、登録済みの相手一覧。","output":"変更なしで戻る場合か、相手の評価更新・リセットの結果outcome。","boundary":"この抜粋はoutcomeを得るまでです。結果に応じた遮断など後続の処理全体は含みません。信頼済みでも全ての変更が免除されるわけではありません。","selfCheck":"信頼済み相手へのTimeoutによる変更と、未登録の相手への変更をどう扱うか説明する"}},{"area":"sync","title":"同期の段階","question":"過去のブロックをそろえる仕事を、どう進める？","role":"同期の仕事を段階ごとに進め、進捗や巻き戻しを扱います。","input":"段階の一覧、前段階の進捗、保存先を持つself。","output":"続行・進捗なし・巻き戻しなど次の制御情報、またはエラー。","boundary":"L232の?は段階の失敗を返します。巻き戻し指示ならL244で巻き戻し、L245で戻ります。各段階の詳細は別実装です。","context":"area:sync","followup":{"context":"area:sync-unwind","question":"巻き戻す段階は、どの順に選ぶ？","role":"保存済み進捗と目標を確認し、同期した順と逆に段階を見て、目標より手前の段階を飛ばします。","input":"巻き戻し先to、問題ブロックbad_block、段階と保存先を持つself。","output":"この抜粋では対象の段階を選びます。外側のunwind全体は成功かPipelineErrorを返します。","boundary":"進捗が目標より小さい段階はSkipped通知後にcontinueします。等しい場合の処理や実際の段階の巻き戻し・保存は後続の範囲です。","selfCheck":"目標番号より進捗番号が小さい段階はどうなるか、巻き戻す順序とともに説明する"}},{"area":"engine","title":"要求の処理と保存待ち","question":"届いた要求と、保存の完了をどう扱う？","role":"Engineの要求や、保存側の完了を専用スレッドで扱います。","input":"Engineの要求、保存完了の出来事、保存の進み具合。","output":"出来事を処理し続けます。このrun自体は値を返さない形です。","boundary":"保存が追いつかない条件ではL564で保存側を待ち、通常はL569で入力を待ちます。保存監視などのエラーではループを終える場合があります。","context":"startup:tree","followup":{"context":"area:engine-timestamp","question":"次の候補の時刻が同じだったら、どうなる？","role":"候補を作るための属性の時刻を、現在のヘッダーの時刻と比べます。","input":"候補の属性attrと、比較するヘッダーheader。","output":"属性時刻が大きければOk(())、小さいか同じならInvalidTimestamp。","boundary":"この関数は時刻の条件だけを検査します。Okは候補の作成完了や、履歴の採用・確定を意味しません。","selfCheck":"候補の属性時刻が現在のヘッダーと同じ場合と、大きい場合の戻り値を説明する"}},{"area":"execution","title":"ブロックの実行","question":"ブロック内の要求を、どの順に実行する？","role":"ブロック内のトランザクションを順に実行し、前後の状態変更と結果をまとめます。","input":"送信者が復元されたトランザクションを含むブロックと、状態を扱うself。","output":"レシートなどを含むブロック実行結果、または実行エラー。","boundary":"L621の?は一件の実行失敗を返します。L631の成功返却は、保存先へcommitしたことや履歴の確定を示しません。","context":"area:execution","followup":{"context":"area:execution-receipt","question":"失敗した実行も、レシートには残る？","role":"実行結果から、種類・成功印・累積ガス・ログを持つレシートを組み立てます。","input":"tx_type、result、cumulative_gas_usedを含む実行の情報ctx。","output":"Receiptという実行結果の記録。戻り値はResultではありません。","boundary":"この関数は実行済みの結果を記録へ移します。実行失敗ならsuccessがfalseになり、レシートの作成自体をErrにする分岐はありません。保存や確定も別です。","selfCheck":"実行結果が失敗だった場合、レシート自体が作られないのか、成功印はどうなるか説明する"}},{"area":"payload","title":"ブロック候補の作成","question":"ブロック候補を作る処理へ、何を渡す？","role":"候補作成の引数とノード部品を、担当処理へ渡します。","input":"候補作成の引数args、EVM設定、状態参照、プール、作成設定。","output":"候補作成の結果BuildOutcome、またはPayloadBuilderError。","boundary":"この入口は担当処理のResultをそのまま返します。取引の全採用条件は抜粋の外で、候補作成は履歴の採用・確定とは別です。","context":"area:payload","followup":{"context":"area:payload-cancel","question":"候補に入れない要求と、候補作成の中止は同じ？","role":"要求が残りのガス枠に収まるかを判定し、超過なら飛ばし、中止されていれば候補作成を終えます。","input":"選んだ要求pool_tx、ガス枠と使用量、適用ルール、中止状態cancel。","output":"超過なら次の要求へ進み、中止検査が真ならOk(BuildOutcome::Cancelled)を返します。","boundary":"無効の印は候補選択のイテレーターに付けます。プール全体から削除したとまでは言えません。continueすると、この回の中止検査へは進みません。","selfCheck":"ガス枠超過でスキップする場合と、その後の中止検査が真の場合の違いを説明する"}},{"area":"storage","title":"保存の確定","question":"状態の変更は、どう保存先へ確定する？","role":"書き込み用の部品が持つ変更を、保存先へ確定します。","input":"書き込み中のDB操作、静的ファイル、待機中のバッチを持つself。","output":"成功ならOk(())、失敗なら保存処理のエラー。","boundary":"通常の保存と巻き戻しを分けます。?の付いた保存が失敗すればエラーを返します。変更データの作成や、全保存先の原子性はこの範囲では示しません。","context":"area:storage","followup":{"context":"area:storage-account","question":"アドレスから読むとき、値なしとエラーをどう分ける？","role":"保存形式の設定を見て、アドレスそのものか、そのハッシュをキーに現在のアカウントを読みます。","input":"アドレスaddressと、保存形式・DB参照を持つself。","output":"ProviderResult<Option<Account>>。見つかった値、値なし、読取失敗を区別します。","boundary":"読取専用の入口で、残高を増減したり送信を実行する処理ではありません。Noneは値なしで、DBの読取失敗とは別です。","selfCheck":"ハッシュ形式が有効の場合のキーと、見つからない場合のOptionと、読取エラーを区別する"}},{"area":"extension","title":"拡張機能への通知","question":"新しい出来事を、拡張機能へどう伝える？","role":"通知経路の空きを待ってから、通知の出所とデータを渡します。","input":"sourceという出所と、notificationという出来事の通知。","output":"通知経路への送信が成功したか、SendErrorか。","boundary":"L618は受け付け可能になるまで待つ箇所です。L619の送信成功は拡張機能の処理完了やブロック確定を意味しません。","context":"area:extension","followup":{"context":"area:extension-reorg","question":"履歴の差し替え通知から、新旧どちらを取れる？","role":"通知の種類に応じて、新しく採用した履歴と、外した古い履歴を別々に取り出します。","input":"採用・差し替え・取り消しのいずれかの通知self。","output":"committed_chainは新しい履歴、reverted_chainは古い履歴を、それぞれSomeかNoneで返します。","boundary":"履歴を取り出す関数で、差し替え自体を実行する処理ではありません。採用通知と履歴の確定も別です。cloneはArcの共有参照を複製します。","selfCheck":"差し替え通知では新旧どちらを取得でき、単なる取り消し通知では何が得られないか説明する"}},{"area":"foundation","title":"チェーンの設定","question":"チェーンの設定をどう読み、失敗したらどうなる？","role":"組み込みmainnet用の設定を読み、ノードで使う設定値を組み立てます。","input":"Rethに組み込まれたmainnet.jsonの文字列と、mainnet用のルール設定。","output":"共有用のChainSpecというチェーン設定。","boundary":"L117のexpectは読み取り失敗時にpanicを起こします。利用者の任意ファイルの解析や、接続・同期完了を示す処理ではありません。","context":"area:foundation","followup":{"context":"area:foundation-fee","question":"時刻で使う手数料の設定を、どう選ぶ？","role":"固定設定ならそのまま返し、可変設定なら指定された時刻で有効なルールの設定を選びます。","input":"呼び出し元が渡すtimestampと、ルール・手数料の設定を持つself。","output":"計算に使うBaseFeeParams。最終的な支払額ではありません。","boundary":"可変一覧を逆順に見て最初に有効なものを返します。該当なしなら一覧の先頭、空一覧ならEthereumの既定設定です。この関数は現在時刻の取得や手数料額の計算をしません。","selfCheck":"可変設定で有効なルールが見つからない場合と、一覧自体が空の場合の代替値を説明する"}}]};
